#!/usr/bin/env bash
#
# sys_report.sh - collect basic host metrics and print them as one CSV line.
#
# Field order:
#   hostname, kernel release, uptime, free MB, root disk use%, load1, users, date
#
set -u

get_hostname() {
    local name
    name=$(hostname 2>/dev/null)
    if [ -z "$name" ]; then
        name=$(uname -n)
    fi
    printf '%s' "$name"
}

get_kernel_release() {
    uname -r
}

get_uptime_pretty() {
    local pretty
    pretty=$(uptime -p 2>/dev/null)
    if [ -z "$pretty" ]; then
        pretty="up $(cut -d. -f1 /proc/uptime) seconds"
    fi
    printf '%s' "$pretty"
}

get_free_mem_mb() {
    free -m | awk '$1 == "Mem:" { print $4 }'
}

get_root_disk_usage() {
    df -P / | awk 'NR == 2 { print $5 }'
}

get_load_1min() {
    cut -d' ' -f1 /proc/loadavg
}

get_logged_in_users() {
    who | wc -l | tr -d ' '
}

get_datetime() {
    date '+%Y-%m-%d %H:%M:%S'
}

build_report() {
    local fields=()
    fields+=("$(get_hostname)")
    fields+=("$(get_kernel_release)")
    fields+=("$(get_uptime_pretty)")
    fields+=("$(get_free_mem_mb)")
    fields+=("$(get_root_disk_usage)")
    fields+=("$(get_load_1min)")
    fields+=("$(get_logged_in_users)")
    fields+=("$(get_datetime)")

    local IFS=','
    printf '%s\n' "${fields[*]}"
}

main() {
    build_report
}

main "$@"

