#!/usr/bin/env bash
# log_summary.sh - summarise an NGINX access log (combined format)

set -u

usage() {
    echo "Usage: $(basename "$0") <access.log>" >&2
}

total_requests() {
    wc -l < "$1" | tr -d ' '
}

unique_ips() {
    awk '{print $1}' "$1" | sort -u | wc -l | tr -d ' '
}

# Prints "<count> <ip>" for the busiest client
top_ip_line() {
    awk '{print $1}' "$1" | sort | uniq -c | sort -rn | head -n 1
}

error_count() {
    awk '$9 >= 400 {n++} END {print n+0}' "$1"
}

# Extracts the [dd/Mon/yyyy:HH:MM:SS +zzzz] field of the first log line
first_timestamp() {
    sed -n '1s/.*\[\([^]]*\)\].*/\1/p' "$1"
}

last_timestamp() {
    tail -n 1 "$1" | sed -n 's/.*\[\([^]]*\)\].*/\1/p'
}

unique_agents() {
    awk -F'"' 'NF >= 6 {print $6}' "$1" | sort -u | wc -l | tr -d ' '
}

main() {
    if [ "$#" -lt 1 ]; then
        usage
        return 2
    fi

    local logfile=$1
    if [ ! -r "$logfile" ]; then
        echo "$logfile: cannot read file" >&2
        return 1
    fi

    local total
    total=$(total_requests "$logfile")
    if [ "$total" -eq 0 ]; then
        echo "$logfile: no requests logged" >&2
        return 1
    fi

    local ips=$(unique_ips "$logfile")
    local top=$(top_ip_line "$logfile")
    local top_count=${top%% *}
    local top_addr=${top##* }
    local errors=$(error_count "$logfile")
    local first=$(first_timestamp "$logfile")
    local last=$(last_timestamp "$logfile")
    local agents=$(unique_agents "$logfile")

    echo "=== Summary for $logfile ==="
    echo "Total Requests: $total"
    echo "Unique IPs: $ips"
    echo "Most Active IP: $top_addr"
    echo "Requests by Most Active IP: $top_count"
    echo "HTTP Errors (>=400): $errors"
    echo "First Request: $first"
    echo "Last Request: $last"
    echo "Unique User Agents: $agents"
}

main "$@"

