#!/usr/bin/env bash
#
# git_report.sh - print key/value metadata about the current Git repository.
# Must be run from inside a Git working tree.

set -u

die() {
    echo "git_report.sh: $1" >&2
    exit 1
}

require_repo() {
    command -v git >/dev/null 2>&1 || die "git is not installed"
    local top
    top=$(git rev-parse --show-toplevel 2>/dev/null) || die "not a git repository"
    printf '%s\n' "$top"
}

current_branch() {
    local name
    name=$(git symbolic-ref --quiet --short HEAD 2>/dev/null)
    if [ -n "$name" ]; then
        printf '%s\n' "$name"
    else
        printf 'detached at %s\n' "$(git rev-parse --short HEAD)"
    fi
}

commit_count() {
    git rev-list --count HEAD 2>/dev/null || echo 0
}

uncommitted_changes() {
    local status
    status=$(git status --porcelain --untracked-files=no)
    if [ -z "$status" ]; then
        echo 0
    else
        printf '%s\n' "$status" | wc -l | tr -d ' '
    fi
}

latest_tag() {
    git describe --tags --abbrev=0 2>/dev/null || echo "(none)"
}

origin_url() {
    git config --get remote.origin.url 2>/dev/null || echo "(no remote)"
}

user_email() {
    git config --get user.email 2>/dev/null || echo "(unset)"
}

merged_branch_count() {
    local branch merged
    branch=$(current_branch)
    merged=$(git branch --merged HEAD --format='%(refname:short)' | grep -vxF "$branch")
    if [ -z "$merged" ]; then
        echo 0
    else
        printf '%s\n' "$merged" | wc -l | tr -d ' '
    fi
}

main() {
    local root
    root=$(require_repo)
    cd "$root" || die "cannot enter $root"

    echo "Current Branch: $(current_branch)"
    echo "Repository Root: $root"
    echo "Total Commits: $(commit_count)"
    echo "Uncommitted Changes: $(uncommitted_changes)"
    echo "Latest Tag: $(latest_tag)"
    echo "Remote Origin: $(origin_url)"
    echo "User Email: $(user_email)"
    echo "Merged Branches: $(merged_branch_count)"
}

main "$@"

