#!/usr/bin/env bash
# backup_dir.sh — archive a source directory into a destination with an audit trail.

set -u

usage() {
    echo "Usage: $(basename "$0") <source-dir> <destination-dir>" >&2
    exit 2
}

validate_dirs() {
    local src=$1 dst=$2
    if [ ! -d "$src" ]; then
        echo "error: source '$src' is not a directory" >&2
        return 1
    fi
    if [ ! -d "$dst" ]; then
        echo "error: destination '$dst' is not a directory" >&2
        return 1
    fi
    return 0
}

source_size() {
    du -sh "$1" | cut -f1
}

file_count() {
    find "$1" -type f | wc -l
}

archive_name() {
    local base=$(basename "$1")
    echo "${base}-${2}.tar.gz"
}

file_size() {
    stat -c '%s' "$1"
}

md5_of() {
    md5sum "$1" | awk '{print $1}'
}

owner_of() {
    stat -c '%U' "$1"
}

dest_free_space() {
    df -h "$1" | awk 'NR==2 {print $4}'
}

create_archive() {
    local archive=$1 src=$2 parent base
    parent=$(dirname "$src")
    base=$(basename "$src")
    tar -czf "$archive" -C "$parent" "$base"
}

main() {
    [ "$#" -eq 2 ] || usage
    local src=$1 dst=$2
    validate_dirs "$src" "$dst" || exit 1

    local stamp size count name
    stamp=$(date +%Y%m%d)
    size=$(source_size "$src")
    count=$(file_count "$src")
    name=$(archive_name "$src" "$stamp")

    local archive="$dst/$name"
    create_archive "$archive" "$src" || exit 1

    echo "date:             $stamp"
    echo "source:           $src"
    echo "source size:      $size"
    echo "file count:       $count"
    echo "archive:          $archive"
    echo "archive bytes:    $(file_size "$archive")"
    echo "archive md5:      $(md5_of "$archive")"
    echo "archive owner:    $(owner_of "$archive")"
    echo "destination free: $(dest_free_space "$dst")"
}

main "$@"

