#!/usr/bin/env bash
# audit_users.sh - summarise local user accounts and home directories.

set -u

PASSWD_FILE=/etc/passwd
GROUP_FILE=/etc/group
HOME_ROOT=/home

total_users() {
    awk 'END {print NR}' "$PASSWD_FILE"
}

root_uid() {
    awk -F: '$1 == "root" {print $3; exit}' "$PASSWD_FILE"
}

bash_shell_users() {
    awk -F: '$7 == "/bin/bash" {c++} END {print c+0}' "$PASSWD_FILE"
}

sudo_group_members() {
    local entry gid secondary primary
    entry=$(awk -F: '$1 == "sudo"' "$GROUP_FILE")
    if [ -z "$entry" ]; then
        echo 0
        return
    fi
    gid=$(echo "$entry" | cut -d: -f3)
    secondary=$(echo "$entry" | cut -d: -f4 | tr ',' '\n' | grep -c '[^[:space:]]')
    primary=$(awk -F: -v g="$gid" '$4 == g {c++} END {print c+0}' "$PASSWD_FILE")
    echo $((secondary + primary))
}

last_login_record() {
    last -n 1 2>/dev/null | head -n 1
}

last_login_user() {
    local record
    record=$(last_login_record)
    echo "${record%% *}" | awk '{print ($1 == "" ? "unknown" : $1)}'
}

last_login_time() {
    local record
    record=$(last_login_record)
    if [ -z "$record" ]; then
        echo "unknown"
        return
    fi
    echo "$record" | awk '{printf "%s %s %s %s\n", $4, $5, $6, $7}'
}

home_directory_count() {
    find "$HOME_ROOT" -mindepth 1 -maxdepth 1 -type d 2>/dev/null | wc -l
}

largest_home_mb() {
    local biggest
    biggest=$(du -sm "$HOME_ROOT"/* 2>/dev/null | sort -rn | head -n 1)
    if [ -z "$biggest" ]; then
        echo 0
        return
    fi
    echo "${biggest%%[[:space:]]*}"
}

main() {
    if [ ! -r "$PASSWD_FILE" ]; then
        echo "audit_users.sh: cannot read $PASSWD_FILE" >&2
        exit 1
    fi

    echo "User account audit for $(hostname)"
    echo "-----------------------------------"
    printf 'Total user accounts      : %s\n' "$(total_users)"
    printf 'UID of root              : %s\n' "$(root_uid)"
    printf 'Users with /bin/bash     : %s\n' "$(bash_shell_users)"
    printf 'Members of sudo group    : %s\n' "$(sudo_group_members)"
    printf 'Last login by user       : %s\n' "$(last_login_user)"
    printf 'Last login time          : %s\n' "$(last_login_time)"
    printf 'Directories in %-10s: %s\n' "$HOME_ROOT" "$(home_directory_count)"
    printf 'Largest home directory   : %s MB\n' "$(largest_home_mb)"
}

main "$@"

