#!/usr/bin/env bash
# env_verify.sh - report build environment details as shell variable exports
set -u

MISSING=0

emit() {
    printf '%s="%s"\n' "$1" "$2"
}

require_tool() {
    local tool=$1
    if ! command -v "$tool" >/dev/null 2>&1; then
        echo "env_verify.sh: required tool not found: $tool" >&2
        MISSING=$((MISSING + 1))
        return 1
    fi
    return 0
}

kernel_name() {
    echo "$(uname -s)"
}

machine_arch() {
    echo "$(uname -m)"
}

node_version() {
    local raw
    raw=$(node --version 2>/dev/null)
    echo "${raw#v}"
}

python_version() {
    local raw
    raw=$(python3 --version 2>&1)
    echo "${raw#Python }"
}

docker_version() {
    docker version --format '{{.Client.Version}}' 2>/dev/null
}

make_version() {
    local first
    first=$(make --version 2>/dev/null | head -n 1)
    echo "${first##* }"
}

cpu_cores() {
    nproc
}

ram_available_mb() {
    free -m | awk '/^Mem:/ { print $NF }'
}

main() {
    emit OS_KERNEL "$(kernel_name)"
    emit ARCH "$(machine_arch)"
    require_tool node && emit NODE_VER "$(node_version)"
    require_tool python3 && emit PYTHON_VER "$(python_version)"
    require_tool docker && emit DOCKER_VER "$(docker_version)"
    require_tool make && emit MAKE_VER "$(make_version)"
    require_tool nproc && emit CPU_CORES "$(cpu_cores)"
    require_tool free && emit RAM_AVAIL_MB "$(ram_available_mb)"

    if [ "$MISSING" -gt 0 ]; then
        echo "env_verify.sh: $MISSING component(s) missing; build may fail" >&2
        return 1
    fi
    return 0
}

main "$@"

