#!/usr/bin/env bash
# Report the health of systemd services matching a pattern.
set -uo pipefail

manager_property() {
    systemctl show --property="$1" --value 2>/dev/null
}

memory_kb() {
    local raw
    raw=$(manager_property MemoryCurrent)
    if [[ $raw =~ ^[0-9]+$ ]]; then
        echo $(( raw / 1024 ))
    else
        echo 0
    fi
}

manager_pid() {
    local raw
    raw=$(manager_property MainPID)
    if [[ $raw =~ ^[0-9]+$ ]]; then
        echo "$raw"
    else
        echo 1
    fi
}

count_units() {
    systemctl list-units --type=service --all --no-legend --plain "$@" 2>/dev/null | wc -l
}

count_matching() {
    systemctl list-units --type=service --state=active --no-legend --plain 2>/dev/null |
        awk '{print $1}' | grep -c -- "$1"
}

to_seconds() {
    local spec=$1 total=0 num unit
    while [[ $spec =~ ^([0-9]+(\.[0-9]+)?)(min|ms|s) ]]; do
        num=${BASH_REMATCH[1]}
        unit=${BASH_REMATCH[3]}
        case $unit in
            min) total=$(awk -v t="$total" -v n="$num" 'BEGIN{print t + n * 60}') ;;
            s)   total=$(awk -v t="$total" -v n="$num" 'BEGIN{print t + n}') ;;
            ms)  total=$(awk -v t="$total" -v n="$num" 'BEGIN{print t + n / 1000}') ;;
        esac
        spec=${spec#"${BASH_REMATCH[0]}"}
    done
    printf '%.0f\n' "$total"
}

boot_seconds() {
    local report spec
    report=$(systemd-analyze time 2>/dev/null)
    spec=$(awk -v tag="($1)" '{for (i = 2; i <= NF; i++) if ($i == tag) print $(i - 1)}' <<<"$report")
    to_seconds "${spec:-0s}"
}

audit() {
    local pattern=${1:?usage: audit PATTERN}
    local memory pid units active failed target kernel userspace
    memory=$(memory_kb)
    pid=$(manager_pid)
    units=$(count_units)
    active=$(count_matching "$pattern")
    failed=$(count_units --state=failed)
    target=$(systemctl get-default 2>/dev/null)
    target=${target%.target}
    kernel=$(boot_seconds kernel)
    userspace=$(boot_seconds userspace)
    printf 'Memory is %s, pid is %s, units are %s, active are %s, failed are %s, target is %s, kernel is %s, userspace is %s.\n' \
        "$memory" "$pid" "$units" "$active" "$failed" "${target:-unknown}" "$kernel" "$userspace"
}

audit "${1:-network}"

