#!/usr/bin/env bash
# Report process resource usage for a given user account.

set -o pipefail

ps_for_user() {
    ps -u "$1" -o pid=,comm=,rss=,pcpu=,nlwp=,stat= 2>/dev/null
}

count_processes() {
    local snapshot=$1
    printf '%s\n' "$snapshot" | grep -c '[^[:space:]]'
}

top_cpu_pid() {
    local snapshot=$1
    printf '%s\n' "$snapshot" | sort -k4,4gr | awk 'NR==1{print $1}'
}

command_of() {
    local snapshot=$1 pid=$2
    printf '%s\n' "$snapshot" | awk -v p="$pid" '$1==p{print $2; exit}'
}

total_memory() {
    local snapshot=$1
    printf '%s\n' "$snapshot" | awk '{sum += $3} END {print sum + 0}'
}

top_mem_pid() {
    local snapshot=$1
    printf '%s\n' "$snapshot" | sort -k3,3nr | awk 'NR==1{print $1}'
}

total_threads() {
    local snapshot=$1
    printf '%s\n' "$snapshot" | awk '{sum += $5} END {print sum + 0}'
}

zombie_count() {
    ps -eo stat= | grep -c '^Z'
}

profile() {
    local username=$1
    local uid
    uid=$(id -u "$username" 2>/dev/null) || {
        printf 'profile: unknown user: %s\n' "$username" >&2
        return 1
    }

    local snapshot
    snapshot=$(ps_for_user "$username")
    if [ -z "$snapshot" ]; then
        printf '0 0 none 0 0 %s 0 %s\n' "$(zombie_count)" "$uid"
        return 0
    fi

    local cpu_pid=$(top_cpu_pid "$snapshot")
    local mem_pid=$(top_mem_pid "$snapshot")
    local nproc=$(count_processes "$snapshot")
    local cpu_cmd=$(command_of "$snapshot" "$cpu_pid")
    local mem_kb=$(total_memory "$snapshot")
    local zombies=$(zombie_count)
    local threads=$(total_threads "$snapshot")

    printf '%s %s %s %s %s %s %s %s\n' \
        "$nproc" "$cpu_pid" "$cpu_cmd" "$mem_kb" \
        "$mem_pid" "$zombies" "$threads" "$uid"
}

main() {
    local target=${1:-$(id -un)}
    profile "$target"
}

main "$@"

