#!/usr/bin/env bash
# Report login history facts for one or more users from the wtmp/auth log.
set -u

WTMP=${WTMP:-/var/log/wtmp}

# Raw session lines belonging to a single user, without the trailing
# "wtmp begins" banner and blank lines that last(1) appends.
last_lines() {
    last -F -i -f "$WTMP" "$1" 2>/dev/null | sed -e '/^$/d' -e '/^wtmp begins/d'
}

successful_logins() {
    last_lines "$1" | wc -l
}

last_ip() {
    local ip
    ip=$(last_lines "$1" | awk 'NR == 1 { print $3 }')
    printf '%s\n' "${ip:-unknown}"
}

unique_hosts() {
    local hosts
    hosts=$(last_lines "$1" | awk '$3 !~ /^[A-Z][a-z][a-z]$/ { print $3 }')
    printf '%s\n' "$hosts" | sed '/^$/d' | sort -u | wc -l
}

longest_session() {
    last_lines "$1" | awk '
        match($0, /\(([0-9]+\+)?[0-9][0-9]:[0-9][0-9]\)$/) {
            d = substr($0, RSTART + 1, RLENGTH - 2)
            days = 0
            if (index(d, "+")) { split(d, a, "+"); days = a[1]; d = a[2] }
            split(d, t, ":")
            mins = days * 1440 + t[1] * 60 + t[2]
            if (mins > max) max = mins
        }
        END { printf "%dd%02dh%02dm\n", max / 1440, (max % 1440) / 60, max % 60 }'
}

reboot_count() {
    last -f "$WTMP" reboot 2>/dev/null | awk '$1 == "reboot" { n++ } END { print n + 0 }'
}

first_login() {
    local stamp
    stamp=$(last_lines "$1" | tail -n 1 | awk '{ print $5 "-" $6 "-" $8 }')
    printf '%s\n' "${stamp:--}"
}

logged_in_users() {
    who | wc -l
}

console_idle() {
    local idle
    idle=$(w -h 2>/dev/null | awk '$2 == "tty1" || $2 == "console" { print $5; exit }')
    printf '%s\n' "${idle:-none}"
}

history() {
    local username=$1 logins ip longest reboots hosts first users idle
    if ! id "$username" >/dev/null 2>&1; then
        printf 'no such user: %s\n' "$username" >&2
        return 1
    fi
    logins=$(successful_logins "$username")
    ip=$(last_ip "$username")
    longest=$(longest_session "$username")
    reboots=$(reboot_count)
    hosts=$(unique_hosts "$username")
    first=$(first_login "$username")
    users=$(logged_in_users)
    idle=$(console_idle)
    printf '%s %s %s %s %s %s %s %s\n' \
        "$logins" "$ip" "$longest" "$reboots" "$hosts" "$first" "$users" "$idle"
}

main() {
    local user users=("$@")
    if [ ! -r "$WTMP" ]; then
        printf 'cannot read login log: %s\n' "$WTMP" >&2
        exit 1
    fi
    if [ "${#users[@]}" -eq 0 ]; then
        users=(operator)
    fi
    for user in "${users[@]}"; do
        history "$user"
    done
}

main "$@"

