#!/usr/bin/env bash
# Inspect the loaded kernel modules and report eight metrics about them.

set -u

MODULES_FILE=${MODULES_FILE:-/proc/modules}

load_modules() {
    if [[ ! -r $MODULES_FILE ]]; then
        printf '%s: cannot read loaded module list\n' "$MODULES_FILE" >&2
        return 1
    fi
    cat "$MODULES_FILE"
}

total_modules() {
    local count
    count=$(printf '%s\n' "$1" | grep -c '[^[:space:]]')
    printf '%s\n' "$count"
}

prefix_modules() {
    awk -v pre="$2" 'index($1, pre) == 1 { n++ } END { print n + 0 }' <<<"$1"
}

largest_module() {
    awk '$2 + 0 > max { max = $2 + 0; name = $1 } END { print name, max + 0 }' <<<"$1"
}

unused_modules() {
    awk '$3 + 0 == 0 { n++ } END { print n + 0 }' <<<"$1"
}

build_date() {
    local raw stamp
    raw=$(uname -v)
    stamp=$(grep -oE '[A-Z][a-z]{2} [A-Z][a-z]{2} +[0-9]{1,2} [0-9:]+ ([A-Z]+ )?[0-9]{4}' <<<"$raw")
    if [[ -n $stamp ]]; then
        date -d "$stamp" '+%B %-d, %Y' 2>/dev/null || printf '%s\n' "$stamp"
    else
        printf '%s\n' "$raw"
    fi
}

architecture_label() {
    local machine bits
    machine=$(uname -m)
    bits=$(getconf LONG_BIT)
    printf '%s (%s-bit)\n' "$machine" "$bits"
}

profile() {
    local prefix=${1:?profile: a module name prefix is required}
    local table total matching largest unused release built arch

    table=$(load_modules) || return 1
    total=$(total_modules "$table")
    matching=$(prefix_modules "$table" "$prefix")
    largest=$(largest_module "$table")
    unused=$(unused_modules "$table")
    release=$(uname -r)
    built=$(build_date)
    arch=$(architecture_label)

    printf '%s, %s, %s, %s bytes, %s, %s, %s, %s\n' \
        "$total" "$matching" "${largest%% *}" "${largest##* }" \
        "$unused" "$release" "$built" "$arch"
}

profile "${1:-net}"

