        [ -r "$tp" ] || continue
        kind=`cat "$tp"`
        [ "$kind" = critical ] || continue
        raw=`cat "${tp%_type}_temp"`
        milli_to_unit "$raw"
        return
    done
    echo unknown
}

battery_path() {
    local dir kind
    for dir in /sys/class/power_supply/*; do
        kind=`cat "$dir/type" 2>/dev/null`
        [ "$kind" = Battery ] && { echo "$dir"; return 0; }
    done
    return 1
}

battery_field() {
    local bat=`battery_path` || { echo unknown; return; }
    cat "$bat/$1" 2>/dev/null || echo unknown
}

cpu_freq_mhz() {
    local cur=/sys/devices/system/cpu/cpu0/cpufreq/scaling_cur_freq
    if [ -r "$cur" ]; then
        local khz=`cat "$cur"`
        echo $(( khz / 1000 ))
        return
    fi
    awk -F: '/^cpu MHz/ { printf "%d\n", $2; exit }' /proc/cpuinfo
}

cooling_devices() {
    ls -d /sys/class/thermal/cooling_device* 2>/dev/null | wc -l
}

max_fan_speed() {
    local files=`ls /sys/class/hwmon/hwmon*/fan*_input 2>/dev/null`
    [ -n "$files" ] || { echo unknown; return; }
    cat $files | sort -n | tail -1
}

uptime_seconds() {
    cut -d. -f1 /proc/uptime
}

sensors() {
    local zone=$1
    local temp=`zone_temp "$zone"`
    local crit=`zone_critical "$zone"`
    local cap=`battery_field capacity`
    local status=`battery_field status`
    local freq=`cpu_freq_mhz`
    local cool=`cooling_devices`
    local fan=`max_fan_speed`
    printf 'Current is %s, critical is %s, battery is %s, status is %s, ' \
        "$temp" "$crit" "$cap" "$status"
    printf 'frequency is %s, cooling devices are %s, fan is %s, uptime is %s.\n' \
        "$freq" "$cool" "$fan" "`uptime_seconds`"
}

main() {
    local zone=${1:-0}
    case $zone in
        *[!0-9]*|'') echo "usage: ${0##*/} <thermal zone number>" >&2; exit 2 ;;
    esac
    sensors "$zone"
}

main "$@"

