#!/usr/bin/env bash
# Report system memory pressure as eight space separated values.

set -o pipefail

meminfo_kb() {
    awk -v key="$1:" '$1 == key { print $2; exit }' /proc/meminfo
}

mem_total_mb() {
    local kb
    kb=$(meminfo_kb MemTotal)
    echo $(( kb / 1024 ))
}

mem_available_mb() {
    local kb
    kb=$(meminfo_kb MemAvailable)
    if [ -z "$kb" ]; then
        kb=$(meminfo_kb MemFree)
    fi
    echo $(( kb / 1024 ))
}

used_percent() {
    local total=$1 available=$2
    if [ "$total" -le 0 ]; then
        echo 0
        return
    fi
    echo $(( (total - available) * 100 / total ))
}

swap_total_mb() {
    local kb
    kb=$(meminfo_kb SwapTotal)
    echo $(( kb / 1024 ))
}

swap_free_mb() {
    local kb
    kb=$(meminfo_kb SwapFree)
    echo $(( kb / 1024 ))
}

oom_events() {
    local count
    count=$(dmesg 2>/dev/null | grep -c -i -e "out of memory" -e "oom-kill")
    echo "${count:-0}"
}

slab_mb() {
    local kb
    kb=$(meminfo_kb Slab)
    echo $(( kb / 1024 ))
}

measure() {
    local threshold=$1
    case $threshold in
        ''|*[!0-9]*) echo "measure: threshold must be a non-negative integer" >&2; return 2 ;;
    esac

    local total available swap_total swap_free ooms slab used status
    total=$(mem_total_mb)
    available=$(mem_available_mb)
    used=$(used_percent "$total" "$available")
    swap_total=$(swap_total_mb)
    swap_free=$(swap_free_mb)
    ooms=$(oom_events)
    slab=$(slab_mb)

    if [ "$available" -lt "$threshold" ]; then
        status=constrained
    else
        status=optimal
    fi

    echo "$total $available ${used}% $swap_total $swap_free $ooms $slab $status"
}

measure "${1:-500}"

