#!/usr/bin/env bash
# Audit the cryptographic credentials stored in a key directory.

count_public_keys() {
    find "$1" -maxdepth 1 -type f -name '*.pub' | wc -l
}

count_private_keys() {
    find "$1" -maxdepth 1 -type f ! -name '*.pub' \
        -exec grep -l 'PRIVATE KEY' {} + 2>/dev/null | wc -l
}

first_pub() {
    local dir=$1 pattern=$2 file
    for file in "$dir"/*.pub; do
        [ -f "$file" ] || continue
        if grep -qE "^($pattern)" "$file"; then
            echo "$file"
            return 0
        fi
    done
    return 1
}

rsa_bits() {
    local file bits
    file=$(first_pub "$1" 'ssh-rsa') || { echo NA; return; }
    bits=$(ssh-keygen -l -f "$file" | awk '{print $1}')
    echo "${bits:-NA}"
}

ec_comment() {
    local file comment
    file=$(first_pub "$1" 'ssh-ed25519|ecdsa-sha2|sk-ssh-ed25519') || { echo NA; return; }
    comment=$(awk '{print $3}' "$file")
    echo "${comment:-NA}"
}

fingerprint_hash() {
    local file fingerprint
    file=$(find "$1" -maxdepth 1 -type f -name '*.pub' | sort | head -n 1)
    [ -n "$file" ] || { echo NA; return; }
    fingerprint=$(ssh-keygen -l -f "$file" | awk '{print $2}')
    echo "${fingerprint%%:*}"
}

authorized_keys_mode() {
    local file="$1/authorized_keys"
    [ -f "$file" ] || { echo NA; return; }
    stat -c '%a' "$file"
}

known_hosts_ips() {
    local file="$1/known_hosts"
    [ -f "$file" ] || { echo 0; return; }
    cut -d ' ' -f 1 "$file" | tr ',' '\n' \
        | grep -Ex '[0-9]+(\.[0-9]+){3}' | sort -u | wc -l
}

default_curve() {
    local kex
    kex=$(ssh -Q kex 2>/dev/null | grep -m 1 '^curve')
    [ -n "$kex" ] || { echo NA; return; }
    echo "${kex%%-*}"
}

audit() {
    local directory=$1
    [ -d "$directory" ] || { echo "audit: not a directory: $directory" >&2; return 1; }
    local publics privates bits comment hash mode hosts curve
    publics=$(count_public_keys "$directory")
    privates=$(count_private_keys "$directory")
    bits=$(rsa_bits "$directory")
    comment=$(ec_comment "$directory")
    hash=$(fingerprint_hash "$directory")
    mode=$(authorized_keys_mode "$directory")
    hosts=$(known_hosts_ips "$directory")
    curve=$(default_curve "$directory")
    echo "$publics $privates $bits $comment $hash $mode $hosts $curve"
}

audit "${1:-keys}"

