#!/usr/bin/env bash
# Report the details of a mounted filesystem volume.
set -u

normalize_mount() {
    local raw="$1" path
    case "$raw" in
        root) path="/" ;;
        /*)   path="$raw" ;;
        *)    path="/$raw" ;;
    esac
    path=${path%/}
    printf '%s\n' "${path:-/}"
}

mount_field() {
    findmnt --noheadings --first-only --output "$2" --target "$1" 2>/dev/null
}

capacity_kb() {
    df -Pk -- "$1" | awk 'NR == 2 { print $2 }'
}

free_kb() {
    df -Pk -- "$1" | awk 'NR == 2 { print $4 }'
}

loopback_count() {
    local list
    list=$(losetup --all 2>/dev/null)
    printf '%s\n' "$list" | grep -c '^/dev/loop'
}

tmpfs_count() {
    awk '$3 == "tmpfs"' /proc/self/mounts | wc -l
}

read_only_flag() {
    case ",$1," in
        *,ro,*) printf 'true\n' ;;
        *)      printf 'false\n' ;;
    esac
}

inspect() {
    local path type capacity free device loopbacks temporary options ro
    path=$(normalize_mount "$1")
    type=$(mount_field "$path" FSTYPE)
    if [ -z "$type" ]; then
        printf 'inspect: %s is not a mount point\n' "$path" >&2
        return 1
    fi
    capacity=$(capacity_kb "$path")
    free=$(free_kb "$path")
    device=$(mount_field "$path" SOURCE)
    loopbacks=$(loopback_count)
    temporary=$(tmpfs_count)
    options=$(mount_field "$path" OPTIONS)
    ro=$(read_only_flag "$options")
    printf 'Type is %s, capacity is %s, free is %s, device is %s, ' \
        "$type" "$capacity" "$free" "$device"
    printf 'loopbacks are %s, temporary are %s, read only is %s, options are %s.\n' \
        "$loopbacks" "$temporary" "$ro" "$options"
}

main() {
    local target status=0
    if [ "$#" -eq 0 ]; then
        set -- root
    fi
    if [ -z "$(command -v findmnt)" ]; then
        printf 'inspect: findmnt is required\n' >&2
        return 2
    fi
    for target in "$@"; do
        inspect "$target" || status=1
    done
    return "$status"
}

main "$@"

