#!/usr/bin/env bash
# Basic network discovery sweep: count responders, rtt statistics,
# fastest host, unreachable errors, default gateway and primary DNS.

normalize_subnet() {
    local base dots
    base=$(printf '%s' "$1" | sed 's#/[0-9]*$##; s#\.0$##')
    dots=$(printf '%s' "$base" | tr -cd '.' | wc -c)
    if [ "$dots" -ne 2 ]; then
        echo "normalize_subnet: unsupported subnet '$1'" >&2
        return 1
    fi
    printf '%s\n' "$base"
}

ping_rtt() {
    local out
    out=$(ping -c 1 -W 1 "$1" 2>/dev/null) || return 1
    printf '%s\n' "$out" | sed -n 's/.*time=\([0-9.]\{1,\}\).*/\1/p' | head -n 1
}

probe_host() {
    local rtt
    rtt=$(ping_rtt "$1")
    if [ -n "$rtt" ]; then
        printf '%s %s\n' "$1" "$rtt"
    else
        printf '%s ERR\n' "$1"
    fi
}

scan_subnet() {
    local base=$1 host tmp
    tmp=$(mktemp)
    for host in $(seq 1 254); do
        probe_host "$base.$host" >>"$tmp" &
    done
    wait
    cat "$tmp"
    rm -f "$tmp"
}

summarize() {
    printf '%s\n' "$1" | awk '
        $2 == "ERR" { err++; next }
        { n++; sum += $2
          if (min == "" || $2 < min) { min = $2; fast = $1 }
          if (max == "" || $2 > max) { max = $2 } }
        END {
            if (n == 0) printf "0 - - - - %d\n", err + 0
            else printf "%d %.1f %.1f %.1f %s %d\n", n, min, max, sum / n, fast, err + 0
        }'
}

default_gateway() {
    local gw
    gw=$(ip route show default 2>/dev/null | awk '{print $3; exit}')
    if [ -z "$gw" ]; then
        gw=$(netstat -rn 2>/dev/null | awk '$1 == "default" || $1 == "0.0.0.0" {print $2; exit}')
    fi
    printf '%s\n' "${gw:-unknown}"
}

primary_dns() {
    local dns
    dns=$(awk '/^[[:space:]]*nameserver/ {print $2; exit}' /etc/resolv.conf 2>/dev/null)
    printf '%s\n' "${dns:-unknown}"
}

sweep() {
    local base results stats gw dns
    base=$(normalize_subnet "$1") || return 1
    results=$(scan_subnet "$base")
    stats=$(summarize "$results")
    gw=$(default_gateway)
    dns=$(primary_dns)
    printf '%s %s %s\n' "$stats" "$gw" "$dns"
}

local_subnet() {
    local addr
    addr=$(ip -4 route get 1.1.1.1 2>/dev/null | sed -n 's/.*src \([0-9.]*\).*/\1/p')
    printf '%s\n' "${addr:-192.168.1.1}"
}

main() {
    local target=${1:-$(local_subnet)}
    sweep "$target"
}

main "$@"

