#!/usr/bin/env bash
# Mail transfer agent queue health inspector.
set -uo pipefail

queue_messages() {
    find "$1" -type f ! -name '.*' 2>/dev/null | sort
}

count_messages() {
    local files
    files=$(queue_messages "$1")
    printf '%s\n' "$files" | grep -c .
}

largest_size_kb() {
    local bytes
    bytes=$(find "$1" -type f -printf '%s\n' 2>/dev/null | sort -n | tail -1)
    echo $(( ( ${bytes:-0} + 1023 ) / 1024 ))
}

rank_field() {
    # Ranks the addresses/domains harvested from a header, most frequent first.
    local dir=$1 header=$2 field=$3
    local addresses
    addresses=$(grep -rhoiE "^${header}: *<?[^ <>]+@[^ <>]+" "$dir" 2>/dev/null)
    printf '%s\n' "$addresses" | awk '{print $2}' | tr -d '<>' |
        cut -d@ -f"$field" | sort | uniq -c | sort -rn
}

top_sender() {
    local sender
    sender=$(rank_field "$1" From 1-2 | head -1 | awk '{print $2}')
    echo "${sender:-no sender}"
}

deferred_timeouts() {
    local reasons
    reasons=$(grep -rliE 'connection timed out|timeout while' "$1" 2>/dev/null)
    printf '%s\n' "$reasons" | grep -c .
}

oldest_timestamp() {
    local stamp
    stamp=$(find "$1" -type f -printf '%T@ %TY-%Tm-%Td %TH:%TM\n' 2>/dev/null | sort -n | head -1)
    if [ -n "$stamp" ]; then
        echo "${stamp#* }"
    else
        echo "no messages"
    fi
}

active_agents() {
    local procs
    procs=$(ps -eo comm= 2>/dev/null)
    printf '%s\n' "$procs" | grep -cE '^(smtp|smtpd|lmtp|local|virtual|pipe)$'
}

queue_disk_usage() {
    du -sh "$1" 2>/dev/null | cut -f1
}

top_domain() {
    local domain
    domain=$(rank_field "$1" To 2 | head -1 | awk '{print $2}')
    echo "${domain:-no domain}"
}

inspect() {
    local queue=$1
    if [ ! -d "$queue" ]; then
        echo "inspect: $queue: no such queue directory" >&2
        return 1
    fi
    local total largest sender deferred oldest agents usage domain
    total=$(count_messages "$queue")
    largest=$(largest_size_kb "$queue")
    sender=$(top_sender "$queue")
    deferred=$(deferred_timeouts "$queue")
    oldest=$(oldest_timestamp "$queue")
    agents=$(active_agents)
    usage=$(queue_disk_usage "$queue")
    domain=$(top_domain "$queue")
