#!/usr/bin/env bash
# Review HAProxy style load balancer configurations.

count_blocks() {
    local config=$1 keyword=$2
    grep -cE "^[[:space:]]*${keyword}([[:space:]]|\$)" "$config"
}

count_frontends() {
    local config=$1
    local named=$(count_blocks "$config" frontend)
    local combined=$(count_blocks "$config" listen)
    printf '%s\n' "$((named + combined))"
}

count_backends() {
    local config=$1
    local pools=$(count_blocks "$config" backend)
    local combined=$(count_blocks "$config" listen)
    printf '%s\n' "$((pools + combined))"
}

section_value() {
    local config=$1 section=$2 key=$3
    awk -v sec="$section" -v key="$key" '
        $1 == "global" || $1 == "defaults" || $1 == "frontend" ||
        $1 == "backend" || $1 == "listen" { cur = $1 }
        cur == sec && $1 == key { print $2; exit }
    ' "$config"
}

timeout_value() {
    local config=$1 kind=$2
    awk -v kind="$kind" '
        $1 == "global" || $1 == "defaults" || $1 == "frontend" ||
        $1 == "backend" || $1 == "listen" { cur = $1 }
        cur == "defaults" && $1 == "timeout" && $2 == kind { print $3; exit }
    ' "$config"
}

errorfile_path() {
    awk '$1 == "errorfile" && $2 == "503" { print $3; exit }' "$1"
}

count_servers() {
    grep -cE '^[[:space:]]*server[[:space:]]' "$1"
}

extract() {
    local config=$1
    if [ ! -r "$config" ]; then
        printf 'cannot read %s\n' "$config" >&2
        return 1
    fi
    local frontends=$(count_frontends "$config")
    local backends=$(count_backends "$config")
    local maxconn=$(section_value "$config" global maxconn)
    local client_timeout=$(timeout_value "$config" client)
    local server_timeout=$(timeout_value "$config" server)
    local servers=$(count_servers "$config")
    local errorfile=$(errorfile_path "$config")
    local user=$(section_value "$config" global user)
    printf 'Frontends are %s, backends are %s, limit is %s, client timeout is %s, ' \
        "$frontends" "$backends" "${maxconn:-unset}" "${client_timeout:-unset}"
    printf 'server timeout is %s, servers are %s, error file is %s, user is %s.\n' \
        "${server_timeout:-unset}" "$servers" "${errorfile:-unset}" "${user:-unset}"
}

main() {
    if [ "$#" -eq 0 ]; then
        printf 'usage: %s config [config ...]\n' "${0##*/}" >&2
        return 2
    fi
    local config status=0
    for config in "$@"; do
        extract "$config" || status=1
    done
    return "$status"
}

main "$@"

