#!/usr/bin/env bash
# Wireless interface connectivity profiler.

get_ssid() {
    local iface=$1 ssid
    ssid=$(iwgetid -r "$iface" 2>/dev/null)
    if [[ -z $ssid ]]; then
        ssid=$(iw dev "$iface" link 2>/dev/null | sed -n 's/^[[:space:]]*SSID: //p')
    fi
    echo "${ssid:-unknown}"
}

get_signal_percent() {
    local iface=$1 line dbm
    line=$(grep -E "^[[:space:]]*$iface:" /proc/net/wireless 2>/dev/null)
    if [[ -n $line ]]; then
        local quality
        quality=$(awk '{gsub(/\./,"",$3); print $3}' <<<"$line")
        echo $(( quality * 100 / 70 ))
        return
    fi
    dbm=$(iw dev "$iface" link 2>/dev/null | awk '/signal:/ {print $2}')
    if [[ -n $dbm ]]; then
        echo $(( 2 * (dbm + 100) ))
    else
        echo 0
    fi
}

get_mac() {
    cat "/sys/class/net/$1/address" 2>/dev/null || echo "00:00:00:00:00:00"
}

get_ipv4() {
    local addr
    addr=$(ip -4 -o addr show dev "$1" 2>/dev/null | awk '{print $4}' | cut -d/ -f1 | head -n1)
    echo "${addr:-0.0.0.0}"
}

get_gateway() {
    local gw
    gw=$(ip route show default dev "$1" 2>/dev/null | awk '{print $3; exit}')
    echo "${gw:-none}"
}

get_dns() {
    local dns
    dns=$(awk '/^nameserver/ {print $2; exit}' /etc/resolv.conf 2>/dev/null)
    echo "${dns:-none}"
}

get_bitrate() {
    local rate
    rate=$(iw dev "$1" link 2>/dev/null | sed -n 's/.*tx bitrate: \([0-9.]*\) MBit.*/\1/p')
    echo "${rate:-0} Mbit/s"
}

get_operstate() {
    cat "/sys/class/net/$1/operstate" 2>/dev/null || echo "unknown"
}

profile() {
    local iface=$1
    local ssid signal mac ip gw dns rate state
    ssid=$(get_ssid "$iface")
    signal=$(get_signal_percent "$iface")
    mac=$(get_mac "$iface")
    ip=$(get_ipv4 "$iface")
    gw=$(get_gateway "$iface")
    dns=$(get_dns)
    rate=$(get_bitrate "$iface")
    state=$(get_operstate "$iface")
    printf 'interface=%s mac=%s ip=%s dns=%s rate=%s state=%s\n' \
        "$iface" "$mac" "$ip" "$dns" "$rate" "$state" >&2
    echo "Connected to $ssid at $signal percent signal, gateway $gw"
}

main() {
    local iface=${1:-wlan0}
    profile "$iface"
}

main "$@"

