#!/usr/bin/env bash
# Summarize the executable targets defined in a build automation file.

make_version() {
    local first
    first=$(make --version 2>/dev/null | head -n 1)
    if [ -z "$first" ]; then
        echo "unknown"
    else
        echo "$first"
    fi
}

target_lines() {
    # Print "lineno:target:prereqs" for every explicit colon-delimited label.
    grep -n -E '^[A-Za-z0-9._/@%+-]+[[:space:]]*:([^=]|$)' "$1" |
        sed -E 's/^([0-9]+):([^:]+)[[:space:]]*:[[:space:]]*/\1:\2:/'
}

count_commands() {
    # Recipe lines are the tab-indented lines following the target's header.
    local makefile=$1 start=$2 total count=0 line
    total=$(wc -l < "$makefile")
    while [ "$start" -lt "$total" ]; do
        start=$((start + 1))
        line=$(sed -n "${start}p" "$makefile")
        case $line in
            $'\t'*) count=$((count + 1)) ;;
            '') ;;
            *) break ;;
        esac
    done
    echo "$count"
}

count_deps() {
    local deps
    deps=$(echo "$1" | tr -s '[:space:]' ' ')
    set -- $deps
    echo "$#"
}

target_mtime() {
    if [ -e "$1" ]; then
        date -r "$1" '+%Y-%m-%d %H:%M:%S'
    else
        echo "absent"
    fi
}

analyze() {
    local makefile=$1 entry lineno target prereqs commands deps stamp
    if [ ! -f "$makefile" ]; then
        echo "analyze: cannot read $makefile" >&2
        return 1
    fi
    echo "Build tool: $(make_version)"
    echo "Working directory: $(pwd)"
    while IFS= read -r entry; do
        lineno=${entry%%:*}
        target=${entry#*:}
        prereqs=${target#*:}
        target=${target%%:*}
        commands=$(count_commands "$makefile" "$lineno")
        deps=$(count_deps "$prereqs")
        stamp=$(target_mtime "$target")
        echo "Target $target has $deps dependencies and $commands commands (modified: $stamp)"
    done < <(target_lines "$makefile")
}

analyze "${1:-Makefile}"

