#!/usr/bin/env bash
# Rotate old database archives out of a backup directory.
set -uo pipefail

list_archives() {
    find "$1" -maxdepth 1 -type f \
        \( -name '*.sql' -o -name '*.dump' -o -name '*.gz' -o -name '*.tar' \) \
        -printf '%T@ %p\n' 2>/dev/null | sort -n | cut -d' ' -f2-
}

count_archives() {
    list_archives "$1" | grep -c ''
}

oldest_archive() {
    local sorted
    sorted=$(list_archives "$1")
    [ -n "$sorted" ] && head -n 1 <<<"$sorted"
}

archive_date() {
    grep -oE '[0-9]{8}' <<<"$1" | head -n 1
}

age_seconds() {
    local stamp=$1 born now
    born=$(date -d "$stamp" +%s 2>/dev/null) || return 1
    now=$(date +%s)
    echo $((now - born))
}

file_bytes() {
    stat -c '%s' -- "$1"
}

usage_percent() {
    df -P "$1" | awk 'NR == 2 { gsub(/%/, "", $5); print $5 }'
}

rotate() {
    local backups=${1:-} oldest name stamp bytes before after age
    if [ ! -d "$backups" ]; then
        echo "rotate: $backups is not a directory" >&2
        return 1
    fi
    oldest=$(oldest_archive "$backups")
    if [ -z "$oldest" ]; then
        echo "rotate: no archive files found in $backups" >&2
        return 1
    fi
    name=$(basename -- "$oldest")
    stamp=$(archive_date "$name")
    bytes=$(file_bytes "$oldest")
    before=$(usage_percent "$backups")
    if [ -n "$stamp" ]; then
        age=$(age_seconds "$stamp")
        printf 'Candidate %s dated %s, aged %s seconds\n' "$name" "$stamp" "$age" >&2
    fi
    rm -f -- "$oldest" || return 1
    after=$(usage_percent "$backups")
    printf 'Partition usage for %s: %s%% before, %s%% after\n' \
        "$backups" "$before" "$after" >&2
    printf 'Deleted %s freeing %s bytes.\n' "$name" "$bytes"
}

main() {
    local target=${1:-/var/backups} summary before after
    before=$(count_archives "$target")
    summary=$(rotate "$target") || return 1
    echo "$summary"
    after=$(count_archives "$target")
    printf 'Archives deleted this run: %d\n' "$((before - after))"
}

main "$@"

