#!/usr/bin/env bash
# Monitor a search engine (Elasticsearch-style) node and report a health summary.

node_url() {
    local addr=$1 hostpart
    [ "${addr#http}" = "$addr" ] && addr="http://$addr"
    hostpart=${addr#*://}
    case $hostpart in
        *:[0-9]*) ;;
        *) addr="$addr:9200" ;;
    esac
    printf '%s' "$addr"
}

api_get() {
    curl -s -f --max-time 5 "$(node_url "$1")$2"
}

json_value() {
    printf '%s' "$1" | tr ',{}[]' '\n\n\n\n\n' | grep -m1 "\"$2\"" |
        sed 's/.*: *//; s/^"//; s/"$//'
}

count_indices() {
    local listing
    listing=$(api_get "$1" "/_cat/indices?h=index")
    printf '%s' "$listing" | grep -c '[^[:space:]]'
}

num_word() {
    case $1 in
        0) echo zero ;; 1) echo one ;; 2) echo two ;; 3) echo three ;;
        4) echo four ;; 5) echo five ;; 6) echo six ;; 7) echo seven ;;
        8) echo eight ;; 9) echo nine ;; 10) echo ten ;; 11) echo eleven ;;
        12) echo twelve ;; *) echo "$1" ;;
    esac
}

