#!/usr/bin/env bash
# Audit of scheduled system tasks (crontabs, cron.d and run-parts directories).

collect_entries() {
    local file dir user
    for file in /etc/crontab /etc/cron.d/*; do
        [ -f "$file" ] || continue
        awk 'NF>=7 && $1 !~ /^[#@]/ && $0 !~ /^[A-Za-z_]+=/ {
                 sched=$1" "$2" "$3" "$4" "$5; user=$6;
                 $1=$2=$3=$4=$5=$6=""; sub(/^ +/,"");
                 printf "%s\t%s\t%s\n", sched, user, $0 }' "$file"
    done
    for dir in hourly daily weekly monthly; do
        for file in /etc/cron.$dir/*; do
            [ -x "$file" ] || continue
            printf '@%s\troot\t%s\n' "$dir" "$file"
        done
    done
    for user in $(cut -d: -f1 /etc/passwd); do
        crontab -l -u "$user" 2>/dev/null |
            awk -v u="$user" 'NF>=6 && $1 !~ /^#/ && $0 !~ /^[A-Za-z_]+=/ {
                     if ($1 ~ /^@/) { sched=$1; n=1 }
                     else { sched=$1" "$2" "$3" "$4" "$5; n=5 }
                     for (i=1;i<=n;i++) $i="";
                     sub(/^ +/,"");
                     printf "%s\t%s\t%s\n", sched, u, $0 }'
    done
}

classify() {
    local sched="$1" fields
    case "$sched" in
        @hourly)          echo hourly;  return ;;
        @daily|@midnight) echo daily;   return ;;
        @weekly)          echo weekly;  return ;;
        @monthly)         echo monthly; return ;;
        @*)               echo other;   return ;;
    esac
    read -r -a fields <<< "$sched"
    if [ "${fields[3]}" != "*" ] || [ "${fields[2]}" != "*" ]; then echo monthly
    elif [ "${fields[4]}" != "*" ]; then echo weekly
    elif [ "${fields[1]}" != "*" ]; then echo daily
    else echo hourly; fi
}

classify_entries() {
    local sched user cmd freq
    while IFS=$'\t' read -r sched user cmd; do
        freq=$(classify "$sched")
        printf '%s\t%s\t%s\n' "$freq" "$user" "$cmd"
    done
}

count_freq() { awk -F'\t' -v f="$1" '$1==f' | grep -c . ; }

runs_per_month() {
    case "$1" in hourly) echo 720 ;; daily) echo 30 ;;
                 weekly) echo 4 ;; monthly) echo 1 ;; *) echo 0 ;; esac
}

most_frequent() {
    local freq user cmd score best=-1 name="none"
    while IFS=$'\t' read -r freq user cmd; do
        score=$(runs_per_month "$freq")
        if [ "$score" -gt "$best" ]; then
            name=$(basename "${cmd%% *}")
            best=$score
        fi
    done
    echo "$name"
}

analyze() {
    local entries total root regular hourly daily weekly monthly top
    entries=$(collect_entries | classify_entries)
    total=$(grep -c . <<< "$entries")
    root=$(awk -F'\t' '$2=="root"' <<< "$entries" | grep -c .)
    regular=$((total - root))
    hourly=$(count_freq hourly <<< "$entries")
    daily=$(count_freq daily <<< "$entries")
    weekly=$(count_freq weekly <<< "$entries")
    monthly=$(count_freq monthly <<< "$entries")
    top=$(most_frequent <<< "$entries")
    echo "There are $total total tasks, with $root running as the administrative" \
         "root user and $regular as regular users; $hourly run hourly," \
         "$daily daily, $weekly weekly and $monthly monthly, and the most" \
         "frequently run task is '$top'."
}

analyze

