#!/usr/bin/env bash
# Video processing planner: probe a media file and print the 30 fps conversion command.
set -u

probe_stream() {
    local file=$1 selector=$2 entry=$3
    ffprobe -v error -select_streams "$selector" \
        -show_entries "stream=$entry" \
        -of default=noprint_wrappers=1:nokey=1 -- "$file" | head -n 1
}

probe_duration() {
    ffprobe -v error -show_entries format=duration \
        -of default=noprint_wrappers=1:nokey=1 -- "$1" | head -n 1
}

frame_rate() {
    printf '%s\n' "$1" | awk -F/ '{ if (NF==2 && $2>0) printf "%.3f\n", $1/$2; else printf "%.3f\n", $1+0 }'
}

as_hms() {
    printf '%s\n' "$1" | awk '{ t=int($1+0.5); printf "%02d:%02d:%02d\n", t/3600, (t%3600)/60, t%60 }'
}

codec_label() {
    case $1 in
        h264|avc1)  echo "advanced video coding" ;;
        hevc|h265)  echo "high efficiency video coding" ;;
        vp9)        echo "VP9" ;;
        aac)        echo "advanced audio coding" ;;
        mp3)        echo "MPEG audio layer 3" ;;
        "")         echo "no stream" ;;
        *)          echo "$1" ;;
    esac
}

convert() {
    local video=$1
    if [ ! -f "$video" ]; then
        echo "convert: cannot probe '$video': not a regular file" >&2
        return 1
    fi
    local dir; dir=$(dirname -- "$video")
    local name; name=$(basename -- "$video")
    local base=${name%.*}
    local raw_rate; raw_rate=$(probe_stream "$video" v:0 r_frame_rate)
    local rate; rate=$(frame_rate "$raw_rate")
    local width; width=$(probe_stream "$video" v:0 width)
    local height; height=$(probe_stream "$video" v:0 height)
    local seconds; seconds=$(probe_duration "$video")
    local length; length=$(as_hms "$seconds")
    local vcodec; vcodec=$(probe_stream "$video" v:0 codec_name)
    local acodec; acodec=$(probe_stream "$video" a:0 codec_name)
    local vlabel; vlabel=$(codec_label "$vcodec")
    local alabel; alabel=$(codec_label "$acodec")
    local abs_dir; abs_dir=$(cd -- "$dir" && pwd)
    local folder; folder=$(basename -- "$abs_dir")

    echo "The $base file in the $folder directory is encoded with $vlabel and needs conversion."
    echo "Details: ${width}x${height}, $rate fps, $length, audio is $alabel."

    local already; already=$(awk -v r="$rate" 'BEGIN { print (r > 29.9 && r < 30.1) ? "yes" : "no" }')
    if [ "$already" = yes ]; then
        echo "No work required: $name already runs at 30 fps."
        return 0
    fi
    echo "ffmpeg -i \"$video\" -filter:v fps=30 -c:v libx264 -c:a copy \"$abs_dir/$base-30fps.mp4\""
}

if [ $# -eq 0 ]; then
    echo "usage: $(basename -- "$0") VIDEO [VIDEO...]" >&2
    exit 2
fi

status=0
for media in "$@"; do
    convert "$media" || status=1
done
exit "$status"

