#!/usr/bin/env bash
# Inspect orchestration workloads (Kubernetes pods) and report eight values.
set -uo pipefail

kquery() {
    kubectl get pod "$1" -o jsonpath="$2" 2>/dev/null
}

sum_restarts() {
    local counts
    counts=$(kquery "$1" '{range .status.containerStatuses[*]}{.restartCount}{"\n"}{end}')
    awk 'NF{total+=$1} END{print total+0}' <<<"$counts"
}

count_containers() {
    local names
    names=$(kquery "$1" '{.spec.containers[*].name}')
    awk '{print NF}' <<<"$names"
}

sum_cpu() {
    local requests
    requests=$(kquery "$1" '{range .spec.containers[*]}{.resources.requests.cpu}{"\n"}{end}')
    awk 'NF{
             v=$1
             if (v ~ /m$/) { sub(/m$/,"",v); total+=v }
             else { total+=v*1000 }
         }
         END{ printf "%dm\n", total }' <<<"$requests"
}

sum_memory() {
    local requests
    requests=$(kquery "$1" '{range .spec.containers[*]}{.resources.requests.memory}{"\n"}{end}')
    awk 'NF{
             v=$1
             if      (v ~ /Ki$/) { sub(/Ki$/,"",v); total+=v/1024 }
             else if (v ~ /Mi$/) { sub(/Mi$/,"",v); total+=v }
             else if (v ~ /Gi$/) { sub(/Gi$/,"",v); total+=v*1024 }
             else                { total+=v/1048576 }
         }
         END{ printf "%dMi\n", total }' <<<"$requests"
}

fetch() {
    local pod=$1 namespace node phase ip restarts containers cpu memory
    namespace=$(kquery "$pod" '{.metadata.namespace}')
    if [ -z "$namespace" ]; then
        echo "fetch: workload instance '$pod' not found" >&2
        return 1
    fi
    node=$(kquery "$pod" '{.spec.nodeName}')
    phase=$(kquery "$pod" '{.status.phase}' | tr '[:upper:]' '[:lower:]')
    ip=$(kquery "$pod" '{.status.podIP}')
    restarts=$(sum_restarts "$pod")
    containers=$(count_containers "$pod")
    cpu=$(sum_cpu "$pod")
    memory=$(sum_memory "$pod")
    echo "$namespace ${node:-unscheduled} $phase ${ip:-none} $restarts $containers $cpu $memory"
}

main() {
    if [ "$#" -eq 0 ]; then
        echo "usage: ${0##*/} POD [POD...]" >&2
        return 2
    fi
    if ! command -v kubectl >/dev/null 2>&1; then
        echo "${0##*/}: kubectl is required" >&2
        return 3
    fi
    local status=0
    for pod in "$@"; do
        fetch "$pod" || status=1
    done
    return "$status"
}

main "$@"

