#!/usr/bin/env bash
# Audit udev-style hardware management rules and describe what they do.

set -uo pipefail

# Isolate the quoted value belonging to a key inside a rule file.
match_value() {
    local key=$1 file=$2 pair value
    pair=`grep -o "${key}[[:space:]]*[+:]\{0,1\}=[[:space:]]*\"[^\"]*\"" "$file" | head -n 1`
    value=`cut -d '"' -f 2 <<<"$pair"`
    [ -n "$value" ] || value="unspecified"
    printf '%s\n' "$value"
}

# Translate the group digit of an octal mode into words.
permission_phrase() {
    local mode=$1 digits bits
    case $mode in
        [0-7][0-7][0-7] | [0-7][0-7][0-7][0-7]) ;;
        *) printf 'unspecified\n'; return 0 ;;
    esac
    digits=`printf '%04d' "$mode"`
    bits=${digits:2:1}
    case $bits in
        7) printf 'read, write and execute\n' ;;
        6) printf 'read and write\n' ;;
        5) printf 'read and execute\n' ;;
        4) printf 'read-only\n' ;;
        2) printf 'write-only\n' ;;
        0) printf 'no\n' ;;
        *) printf 'restricted\n' ;;
    esac
}

# Reduce a device node name such as video0 to its device class.
device_kind() {
    local trimmed
    trimmed=`sed 's/[0-9]*$//' <<<"$1"`
    printf '%s\n' "${trimmed:-device}"
}

extract() {
    local rule=$1
    if [ ! -r "$rule" ]; then
        printf 'Cannot read rule file: %s\n' "$rule" >&2
        return 1
    fi
    local subsystem action vendor product name symlink group mode perms kind
