    vendor=`match_value "ATTRS{idVendor}" "$rule"`
    product=`match_value "ATTRS{idProduct}" "$rule"`
    name=`match_value "NAME" "$rule"`
    symlink=`match_value "SYMLINK" "$rule"`
    group=`match_value "GROUP" "$rule"`
