    printf 'On %s of a %s device from vendor %s product %s, the rule assigns the %s device as /dev/%s with symlink /dev/%s to the %s group with %s permissions.\n' \
        "$action" "$subsystem" "$vendor" "$product" "$kind" "$name" "$symlink" "$group" "$perms"
}

main() {
    if [ $# -eq 0 ]; then
        printf 'Usage: %s RULE_FILE...\n' "`basename "$0"`" >&2
        return 2
    fi
    local rule status=0
