#!/usr/bin/env bash
# Build a deployment archive for a web application and report its metadata.
set -euo pipefail

project_name() {
    local dir
    dir=$(pwd -P)
    basename "$dir"
}

commit_hash() {
    if git rev-parse --git-dir >/dev/null 2>&1; then
        git rev-parse --short HEAD
    else
        echo "nogit"
    fi
}

build_date() {
    date -u +%Y-%m-%dT%H:%M:%SZ
}

runtime_version() {
    local raw
    raw=$(node --version 2>/dev/null) || { echo "unknown"; return; }
    echo "${raw#v}"
}

app_version() {
    local cfg=${1:-package.json}
    if [ ! -f "$cfg" ]; then
        echo "0.0.0"
        return
    fi
    local line
    line=$(grep -m1 '"version"' "$cfg") || { echo "0.0.0"; return; }
    line=${line#*:}
    line=${line%%,*}
    line=$(tr -d ' "' <<<"$line")
    echo "${line:-0.0.0}"
}

checksum() {
    local out
    out=$(sha256sum "$1")
    echo "${out%% *}"
}

file_size() {
    wc -c <"$1" | tr -d ' '
}

package() {
    local outputdir=$1
    mkdir -p "$outputdir"

    local name commit stamp runtime version
    name=$(project_name)
    commit=$(commit_hash)
    stamp=$(build_date)
    runtime=$(runtime_version)
    version=$(app_version package.json)

    local archive="$outputdir/${name}-${version}-${commit}.tar.gz"
    tar --exclude=.git --exclude="$(basename "$outputdir")" -czf "$archive" .

    local digest size
    digest=$(checksum "$archive")
    size=$(file_size "$archive")

    printf 'project=%s version=%s commit=%s built=%s runtime=node-%s archive=%s sha256=%s bytes=%s\n' \
        "$name" "$version" "$commit" "$stamp" "$runtime" "$archive" "$digest" "$size"
}

package "${1:-dist}"

