#!/usr/bin/env bash
# Extract policy metrics from an iptables-save style firewall configuration.
set -uo pipefail

# Translate an iptables target (ACCEPT/DROP/REJECT) into a human word.
policy_word() {
    case "$1" in
        ACCEPT) echo "allow" ;;
        DROP)   echo "deny" ;;
        REJECT) echo "reject" ;;
        *)      echo "unknown" ;;
    esac
}

# Default policy of a built-in chain, taken from its ":CHAIN POLICY" line.
chain_policy() {
    local found
    found=$(awk -v c=":$2" '$1 == c { print $2; exit }' "$1")
    if [ -z "$found" ] || [ "$found" = "-" ]; then
        echo "ACCEPT"
    else
        echo "$found"
    fi
}

count_rules() {
    awk '/^-A[ \t]/ { n++ } END { print n + 0 }' "$1"
}

count_custom_chains() {
    awk '/^:/ {
             name = substr($1, 2)
             if (name != "INPUT" && name != "OUTPUT" && name != "FORWARD" &&
                 name != "PREROUTING" && name != "POSTROUTING") n++
         }
         END { print n + 0 }' "$1"
}

count_target() {
    awk -v t="$2" '/^-A[ \t]/ && $0 ~ "-j[ \t]+" t "([ \t]|$)" { n++ } END { print n + 0 }' "$1"
}

count_chain_rules() {
    awk -v c="$2" '$1 == "-A" && $2 == c { n++ } END { print n + 0 }' "$1"
}

extract() {
    local policy=$1
    if [ ! -r "$policy" ]; then
        echo "extract: cannot read '$policy'" >&2
        return 1
    fi
    local total custom dropping accepting forwarding raw
    total=$(count_rules "$policy")
    custom=$(count_custom_chains "$policy")
    dropping=$(count_target "$policy" DROP)
    accepting=$(count_target "$policy" ACCEPT)
    forwarding=$(count_chain_rules "$policy" FORWARD)
    raw=$(chain_policy "$policy" INPUT)
    local incoming
    incoming=$(policy_word "$raw")
    raw=$(chain_policy "$policy" OUTPUT)
    local outgoing
    outgoing=$(policy_word "$raw")
    raw=$(chain_policy "$policy" FORWARD)
    local routing
    routing=$(policy_word "$raw")
    printf 'Policy has %s rules with %s incoming, %s outgoing, %s routing, ' \
        "$total" "$incoming" "$outgoing" "$routing"
    printf '%s custom chains, %s dropping rules, %s accepting rules, and %s forwarding rules\n' \
        "$custom" "$dropping" "$accepting" "$forwarding"
}

main() {
    if [ $# -ne 1 ]; then
        echo "usage: $(basename "$0") <firewall-policy-file>" >&2
        exit 2
    fi
    extract "$1"
}

main "$@"

