#!/usr/bin/env bash
# Summarize a BGP routing table export (show ip bgp style output).
set -u

die() {
    printf 'summarize: %s\n' "$1" >&2
    exit 1
}

# Keep only the route entries: a 3 column status field followed by a prefix.
route_lines() {
    grep -E '^[*sdhSri >]{1,3}[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+' -- "$1"
}

summarize() {
    local table="$1"
    [ -f "$table" ] || die "$table: no such file"

    local routes
    routes=$(mktemp)
    trap 'rm -f "$routes"' RETURN
    route_lines "$table" > "$routes"
    [ -s "$routes" ] || die "$table: no routing table entries found"

    local prefixes total active hidden avg origin nexthop memory
    prefixes=$(count_prefixes "$routes")
    total=$(wc -l < "$routes")
    active=$(count_status "$routes" '>')
    hidden=$(count_status "$routes" '[hs]')
    avg=$(avg_path_length "$routes")
    origin=$(origin_as "$routes" | most_frequent)
    nexthop=$(next_hops "$routes" | most_frequent)
    memory=$(memory_used "$table")

    printf '%s, %s, %s, %s, %s, %s, %s, %s\n' \
        "$prefixes" "$total" "$active" "$hidden" "$avg" "$origin" "$nexthop" "$memory"
}

# Distinct prefixes; a blank network column means "same prefix as above".
count_prefixes() {
    awk '{ split(substr($0, 4), f, " ")
           if (f[1] ~ /\//) last = f[1]
           if (last != "" && !(last in seen)) { seen[last] = 1; n++ } }
         END { print n + 0 }' "$1"
}

count_status() {
    cut -c1-3 -- "$1" | grep -c -- "$2"
}

most_frequent() {
    sort | uniq -c | sort -rn | awk 'NR == 1 { print $2 }'
}

next_hops() {
    awk '{ split(substr($0, 4), f, " ")
           if (f[2] ~ /^[0-9]+\./) print f[2] }' "$1"
}

# The origin AS is the last AS number of the path, just before the origin code.
origin_as() {
    awk '{ n = split(substr($0, 4), f, " ")
           if (f[n - 1] ~ /^[0-9]+$/) print f[n - 1] }' "$1"
}

avg_path_length() {
    awk '{ n = split(substr($0, 4), f, " ")
           hops = 0
           for (i = 6; i < n; i++) if (f[i] ~ /^[0-9]+$/) hops++
           if (hops > 0) { sum += hops; paths++ } }
         END { if (paths) printf "%.1f\n", sum / paths; else print "0.0" }' "$1"
}

memory_used() {
    local bytes
    bytes=$(grep -Eio '[0-9]+ (total )?bytes of memory|memory used: *[0-9]+' -- "$1" | grep -oE '[0-9]+' | head -1)
    printf '%s\n' "${bytes:-0}"
}

main() {
    [ $# -eq 1 ] || die "usage: $(basename "$0") <routing-table-file>"
    summarize "$1"
}

main "$@"

