#!/usr/bin/env bash
# Lint the contents of a tape archive and report summary statistics.
set -uo pipefail

archive_listing() {
    tar -tvf "$1" 2>/dev/null
}

filter_type() {
    awk -v t="$1" 'substr($1,1,1) == t'
}

entry_names() {
    awk '{ $1=""; $2=""; $3=""; $4=""; $5=""; sub(/^ +/,""); sub(/ -> .*$/,""); print }'
}

count_type() {
    filter_type "$1" | grep -c ''
}

total_size() {
    filter_type - | awk '{ s += $3 } END { print s+0 }'
}

longest_path() {
    filter_type - | entry_names | awk '{ if (length($0) > m) m = length($0) } END { print m+0 }'
}

top_extension() {
    local ranked
    ranked=$(filter_type - | entry_names | awk -F/ '{ print $NF }' \
        | awk -F. 'NF > 1 { print tolower($NF) }' | sort | uniq -c | sort -rn)
    if [ -z "$ranked" ]; then
        echo "-"
        return
    fi
    head -n 1 <<<"$ranked" | awk '{ print $2 }'
}

year_bound() {
    local years
    years=$(awk '$4 ~ /^[0-9]{4}-/ { print substr($4,1,4) }' | sort -n)
    if [ -z "$years" ]; then
        echo "-"
        return
    fi
    case "$1" in
        min) head -n 1 <<<"$years" ;;
        max) tail -n 1 <<<"$years" ;;
    esac
}

lint() {
    local archive=$1 listing files dirs links size longest ext oldest newest
    listing=$(archive_listing "$archive")
    if [ -z "$listing" ]; then
        printf 'lint: %s: cannot read archive contents\n' "$archive" >&2
        return 1
    fi
    files=$(count_type - <<<"$listing")
    dirs=$(count_type d <<<"$listing")
    links=$(count_type l <<<"$listing")
    size=$(total_size <<<"$listing")
    longest=$(longest_path <<<"$listing")
    ext=$(top_extension <<<"$listing")
    oldest=$(year_bound min <<<"$listing")
    newest=$(year_bound max <<<"$listing")
    printf '%s %s %s %s %s %s %s %s\n' \
        "$files" "$dirs" "$size" "$longest" "$ext" "$oldest" "$newest" "$links"
}

main() {
    if [ "$#" -ne 1 ]; then
        printf 'usage: %s ARCHIVE\n' "$(basename "$0")" >&2
        exit 2
    fi
    if [ ! -f "$1" ]; then
        printf 'lint: %s: No such archive file\n' "$1" >&2
        exit 1
    fi
    lint "$1"
}

main "$@"

