count_plays() {
    grep -cE '^[[:space:]]*-?[[:space:]]*hosts:' "$1"
}

count_tasks() {
    grep -cE '^[[:space:]]+-[[:space:]]+(name|action):' "$1"
}

count_host_groups() {
    local hosts
    hosts=$(sed -nE 's/^[[:space:]]*-?[[:space:]]*hosts:[[:space:]]*(.*)$/\1/p' "$1")
    printf '%s\n' "$hosts" \
        | tr ',' '\n' \
        | sed -E 's/[]["]//g; s/^[[:space:]]+//; s/[[:space:]]+$//' \
        | grep -v '^$' \
        | sort -u \
        | wc -l
}

count_vars() {
    awk '
        /^[[:space:]]*vars:[[:space:]]*$/ { base = match($0, /[^ ]/); invars = 1; next }
        invars {
            if ($0 ~ /^[[:space:]]*(#.*)?$/) next
            here = match($0, /[^ ]/)
            if (here > base && $0 ~ /:/) { n++; next }
            invars = 0
        }
        END { print n + 0 }
    ' "$1"
}

count_includes() {
    grep -cE '^[[:space:]]*-?[[:space:]]*(include|include_tasks|include_vars|import_tasks|import_playbook|import_role):' "$1"
}

most_used_module() {
    local reserved module
    reserved='name|hosts|tasks|handlers|roles|vars|vars_files|tags|when|become|become_user'
    reserved="$reserved|become_method|register|notify|loop|with_items|until|retries|delay"
    reserved="$reserved|ignore_errors|changed_when|failed_when|delegate_to|no_log|gather_facts"
    reserved="$reserved|include|include_tasks|include_vars|import_tasks|import_playbook|import_role"
    module=$(sed -nE 's/^[[:space:]]+(-[[:space:]]+)?([a-z0-9_.]+):.*/\2/p' "$1" \
        | grep -Ev "^($reserved)$" \
        | sort | uniq -c | sort -rn | awk 'NR == 1 { print $2 }')
    printf '%s\n' "${module:-none}"
}

count_tags() {
    sed -nE 's/^[[:space:]]*tags:[[:space:]]*(.*)$/\1/p' "$1" \
        | sed -E 's/[][]//g' \
        | tr ',' '\n' \
        | sed -E 's/^[[:space:]]+//; s/[[:space:]]+$//' \
        | grep -cv '^$'
}

count_escalations() {
    grep -cE '^[[:space:]]*become(_user|_method)?:' "$1"
}

summarize() {
    local playbook=$1
    if [ ! -r "$playbook" ]; then
        printf '%s: cannot read playbook\n' "$playbook" >&2
        return 1
    fi
    local plays tasks groups variables includes module tags escalations
    plays=$(count_plays "$playbook")
    tasks=$(count_tasks "$playbook")
    groups=$(count_host_groups "$playbook")
    variables=$(count_vars "$playbook")
    includes=$(count_includes "$playbook")
    module=$(most_used_module "$playbook")
    tags=$(count_tags "$playbook")
    escalations=$(count_escalations "$playbook")
    printf '%s:%s:%s:%s:%s:%s:%s:%s\n' \
        "$plays" "$tasks" "$groups" "$variables" "$includes" "$module" "$tags" "$escalations"
}

summarize "${1:?usage: $0 PLAYBOOK}"

