#!/usr/bin/env bash
# Report the quota limits and usage of a btrfs subvolume.

set -uo pipefail

subvol_show() {
    btrfs subvolume show -- "$1" 2>/dev/null
}

show_field() {
    local text=$1 label=$2
    printf '%s\n' "$text" | sed -n "s/^[[:space:]]*${label}:[[:space:]]*//p" | head -n 1
}

snapshot_count() {
    local listing
    listing=$(printf '%s\n' "$1" | sed -n '/Snapshot(s):/,$p' | tail -n +2)
    printf '%s\n' "$listing" | grep -c '[^[:space:]]'
}

mount_point() {
    df --output=target -- "$1" 2>/dev/null | tail -n 1
}

compression() {
    local prop
    prop=$(btrfs property get -ts -- "$1" compression 2>/dev/null)
    prop=${prop#compression=}
    printf '%s' "${prop:-none}"
}

fmt_size() {
    local pretty
    pretty=$(printf '%s' "$1" | sed 's/iB$//; s/\.00//')
    printf '%s' "${pretty:-none}"
}

qgroup_row() {
    local mount
    mount=$(mount_point "$1")
    btrfs qgroup show -re --human-readable "$mount" 2>/dev/null |
        awk -v q="0/$2" '$1 == q { print $2, $3, $4, $5 }'
}

inspect() {
    local subvolume=$1 info id gen snaps comp row
    info=$(subvol_show "$subvolume")
    if [[ -z $info ]]; then
        printf '%s is not a btrfs subvolume\n' "$subvolume" >&2
        return 1
    fi
    id=$(show_field "$info" "Subvolume ID")
    gen=$(show_field "$info" "Generation")
    snaps=$(snapshot_count "$info")
    comp=$(compression "$subvolume")
    row=$(qgroup_row "$subvolume" "$id")
    read -r rfer excl max_rfer max_excl <<<"$row"

    local total exclusive total_limit excl_limit
    total=$(fmt_size "$rfer")
    exclusive=$(fmt_size "$excl")
    total_limit=$(fmt_size "$max_rfer")
    excl_limit=$(fmt_size "$max_excl")

    printf 'Subvolume %s generation %s uses %s total and %s exclusive with limits %s and %s, having %s snapshots and using %s compression\n' \
        "$id" "$gen" "$total" "$exclusive" "$total_limit" "$excl_limit" "$snaps" "$comp"
}

main() {
    if [[ $# -ne 1 ]]; then
        printf 'usage: %s <subvolume-path>\n' "${0##*/}" >&2
        return 2
    fi
    inspect "$1"
}

main "$@"

