#!/usr/bin/env bash
# Sentiment / statistics analysis of a raw text document.
set -uo pipefail

POSITIVE_WORDS="good great excellent happy wonderful brilliant love loved
delightful positive pleasant success successful beautiful better best gain
improve improved enjoy enjoyed strong strongest helpful kind"

NEGATIVE_WORDS="bad terrible awful sad horrible hate hated poor negative
unpleasant failure failed ugly worse worst loss lose losing broken weak
weakest useless harmful cruel angry"

normalize() {
    printf '%s' "$1" | tr '[:upper:]' '[:lower:]'
}

tokenize() {
    printf '%s\n' "$1" | tr -cs "[:alpha:]'" '\n' | sed "/^'*$/d"
}

count_tokens() {
    local count
    count=$(wc -l | tr -d '[:space:]')
    printf '%s' "$count"
}

count_matches() {
    awk -v list="$1" '
        BEGIN { n = split(list, w, /[[:space:]]+/); for (i = 1; i <= n; i++) dict[w[i]] = 1 }
        ($0 in dict) { hits++ }
        END { print hits + 0 }'
}

top_long_word() {
    local ranked
    ranked=$(awk 'length($0) > 5 { freq[$0]++ } END { for (k in freq) printf "%d\t%s\n", freq[k], k }' | sort -k1,1nr -k2,2)
    printf '%s' "$(printf '%s\n' "$ranked" | head -n 1 | cut -f2)"
}

first_sentence() {
    local trimmed
    trimmed=$(printf '%s' "$1" | tr '\n' ' ' | sed 's/  */ /g; s/^ //; s/ $//')
    printf '%s' "$trimmed" | sed 's/\([.!?]\).*/\1/'
}

sentiment_score() {
    awk -v p="$1" -v n="$2" -v t="$3" 'BEGIN { if (t == 0) print "0.0000"; else printf "%.4f", (p - n) / t }'
}

analyze() {
    local document="$1" lowered tokens total positive negative score keyword context
    lowered=$(normalize "$document")
    tokens=$(tokenize "$lowered")
    total=$(printf '%s\n' "$tokens" | count_tokens)
    positive=$(printf '%s\n' "$tokens" | count_matches "$POSITIVE_WORDS")
    negative=$(printf '%s\n' "$tokens" | count_matches "$NEGATIVE_WORDS")
    score=$(sentiment_score "$positive" "$negative" "$total")
    keyword=$(printf '%s\n' "$tokens" | top_long_word)
    context=$(first_sentence "$document")

    printf 'total_words: %s\n' "$total"
    printf 'positive_matches: %s\n' "$positive"
    printf 'negative_matches: %s\n' "$negative"
    printf 'sentiment_score: %s\n' "$score"
    printf 'top_long_word: %s\n' "${keyword:-none}"
    printf 'first_sentence: %s\n' "$context"
}

main() {
    local raw
    if [ "$#" -ge 1 ]; then
        if [ ! -r "$1" ]; then
            printf '%s: cannot read file\n' "$1" >&2
            return 1
        fi
        raw=$(cat -- "$1")
    else
        raw=$(cat)
    fi
    analyze "$raw"
}

main "$@"

