#!/usr/bin/env bash
# Report a short profile of a system user: identity, home, sessions, processes.
set -uo pipefail

passwd_entry() {
    getent passwd "$1"
}

field() {
    printf '%s\n' "$1" | cut -d: -f"$2"
}

real_name() {
    local gecos
    gecos=`field "$1" 5`
    local name=${gecos%%,*}
    printf '%s\n' "${name:-(no real name set)}"
}

count_hidden() {
    local home=$1
    if [ ! -d "$home" ]; then
        printf '0\n'
        return 1
    fi
    find "$home" -maxdepth 1 -name '.*' -type f 2>/dev/null | wc -l
}

last_login() {
    local raw
    raw=`lastlog -u "$1" 2>/dev/null | tail -n 1`
    case $raw in
        *'Never logged in'*) printf 'never\n' ;;
        ''|Username*)        printf 'unknown\n' ;;
        *) printf '%s\n' "$raw" |
               awk '{ for (i = 4; i <= NF; i++) printf "%s%s", $i, (i < NF ? " " : "\n") }' ;;
    esac
}

process_count() {
    ps -u "$1" -o pid= 2>/dev/null | wc -l
}

total_rss_kb() {
    ps -u "$1" -o rss= 2>/dev/null | awk '{ total += $1 } END { print total + 0 }'
}

format_kb() {
    awk -v kb="$1" 'BEGIN { printf "%d kB (%.1f MiB)\n", kb, kb / 1024 }'
}

summarize() {
    local username=$1 entry
    if ! entry=`passwd_entry "$username"`; then
        printf 'summarize: no such user: %s\n' "$username" >&2
        return 1
    fi
    local name home shell hidden login procs rss memory
    name=`real_name "$entry"`
    home=`field "$entry" 6`
    shell=`field "$entry" 7`
    hidden=`count_hidden "$home"` ||
        printf 'summarize: home directory %s is missing\n' "$home" >&2
    login=`last_login "$username"`
    procs=`process_count "$username"`
    rss=`total_rss_kb "$username"`
    memory=`format_kb "$rss"`

    printf 'User:           %s\n' "$username"
    printf 'Real name:      %s\n' "$name"
    printf 'Home directory: %s\n' "$home"
    printf 'Dotfiles:       %s\n' "$hidden"
    printf 'Last login:     %s\n' "$login"
    printf 'Processes:      %s\n' "$procs"
    printf 'Resident set:   %s\n' "$memory"
    printf 'Login shell:    %s\n' "$shell"
}

main() {
    local user status=0
    if [ "$#" -eq 0 ]; then
        set -- "`id -un`"
    fi
    for user in "$@"; do
