#!/usr/bin/env bash
# NVMe hardware telemetry collector.
set -uo pipefail

# Read one "key : value" field from the controller identify page.
id_field() {
    local device=$1 key=$2
    nvme id-ctrl "$device" | awk -F':' -v k="$key" '
        { gsub(/[ \t]/, "", $1)
          if ($1 == k) { sub(/^[ \t]+/, "", $2); print $2; exit } }'
}

# Read one "key : value" field from the SMART / health log page.
smart_field() {
    local device=$1 key=$2
    nvme smart-log "$device" | awk -F':' -v k="$key" '
        { gsub(/[ \t]/, "", $1)
          if ($1 == k) { sub(/^[ \t]+/, "", $2); print $2; exit } }'
}

model_number() {
    id_field "$1" mn
}

firmware_version() {
    id_field "$1" fr
}

capacity_gb() {
    local bytes
    bytes=$(id_field "$1" tnvmcap)
    echo $(( bytes / 1000000000 ))
}

temperature_c() {
    local raw=$(smart_field "$1" temperature)
    echo "${raw%% *}"
}

available_spare() {
    local raw=$(smart_field "$1" available_spare)
    echo "${raw%\%}"
}

percentage_used() {
    local raw=$(smart_field "$1" percentage_used)
    echo "${raw%\%}"
}

unsafe_shutdowns() {
    local raw=$(smart_field "$1" unsafe_shutdowns)
    echo "${raw//,/}"
}

media_errors() {
    local raw=$(smart_field "$1" media_errors)
    echo "${raw//,/}"
}

diagnose() {
    local device=$1
    local -a values=()
    values+=("$(model_number "$device")")
    values+=("$(firmware_version "$device")")
    values+=("$(capacity_gb "$device")")
    values+=("$(temperature_c "$device")")
    values+=("$(available_spare "$device")")
    values+=("$(percentage_used "$device")")
    values+=("$(unsafe_shutdowns "$device")")
    values+=("$(media_errors "$device")")
    printf '%s\n' "${values[@]}"
}

main() {
    local device=${1:-/dev/nvme0}
    if ! command -v nvme >/dev/null 2>&1; then
        echo "nvme-cli is required but not installed" >&2
        exit 1
    fi
    if [ ! -b "$device" ]; then
        echo "$device: not an NVMe block device" >&2
        exit 1
    fi
    local -a labels=(Model Firmware "Capacity (GB)" "Temperature (C)" \
                     "Available spare (%)" "Used (%)" "Unsafe shutdowns" "Media errors")
    local -a report
    mapfile -t report < <(diagnose "$device")
    local i
    for i in "${!labels[@]}"; do
        printf '%-22s %s\n' "${labels[$i]}:" "${report[$i]}"
    done
}

main "$@"

