#!/usr/bin/env bash
# Extract summary attributes from a CloudFormation-style YAML template.
set -uo pipefail

section_body() {
    local section=$1 file=$2
    awk -v s="$section" '
        $0 ~ "^"s":" { inside = 1; next }
        inside && /^[^[:space:]]/ { inside = 0 }
        inside' "$file"
}

count_entries() {
    local body
    body=$(section_body "$1" "$2")
    awk '/^  [A-Za-z_][A-Za-z0-9_]*:/ { n++ } END { print n + 0 }' <<<"$body"
}

param_block() {
    local name=$1 file=$2
    section_body Parameters "$file" | awk -v p="  $name:" '
        $0 == p { inside = 1; next }
        inside && /^  [A-Za-z_]/ { inside = 0 }
        inside'
}

top_scalar() {
    local line
    line=$(grep -m1 "^$1:" "$2")
    printf '%s' "${line#*: }" | tr -d "\"'"
}

param_default() {
    local block
    block=$(param_block "$1" "$2")
    awk -F': *' '/^    Default:/ { gsub(/["'\'']/, "", $2); print $2; exit }' <<<"$block"
}

count_allowed_values() {
    local block
    block=$(param_block "$1" "$2")
    awk '
        /^    AllowedValues:/ { f = 1; next }
        f && /^      - / { n++; next }
        f && /^    [A-Za-z_]/ { f = 0 }
        END { print n + 0 }' <<<"$block"
}

file_size_kb() {
    local bytes
    bytes=$(stat -c %s "$1")
    awk -v b="$bytes" 'BEGIN { printf "%.2f", b / 1024 }'
}

extract() {
    local template=$1 region_param
    region_param=$(section_body Parameters "$template" |
        awk '/^  [A-Za-z0-9]*Region[A-Za-z0-9]*:/ { gsub(/[ :]/, ""); print; exit }')
    printf '%s\n' \
        "$(count_entries Parameters "$template")" \
        "$(count_entries Resources "$template")" \
        "$(count_entries Outputs "$template")" \
        "$(top_scalar AWSTemplateFormatVersion "$template")" \
        "$(param_default "$region_param" "$template")" \
        "$(count_allowed_values Environment "$template")" \
        "$(top_scalar Description "$template")" \
        "$(file_size_kb "$template")"
}

main() {
    if [ $# -ne 1 ]; then
        echo "usage: ${0##*/} TEMPLATE" >&2
        exit 2
    fi
    if [ ! -f "$1" ]; then
        echo "${0##*/}: $1: no such template file" >&2
        exit 1
    fi
    local labels=(Parameters Resources Outputs FormatVersion DefaultRegion \
        EnvironmentAllowedValues Description SizeKB)
    local report i=0 value
    report=$(extract "$1")
    while IFS= read -r value; do
        printf '%-26s %s\n' "${labels[i]}:" "$value"
        i=$((i + 1))
    done <<<"$report"
}

main "$@"

