#!/usr/bin/env bash
# Gather enforcement statistics for a named security policy.

POLICY_ROOT="${POLICY_ROOT:-/etc/secpolicy}"

FIELD_LABELS=(
    "enforcing mode" "allowed rules" "denials today" "default user"
    "default role" "enabled booleans" "policy file" "last modified"
)

policy_dir() {
    printf '%s/%s\n' "$POLICY_ROOT" "$1"
}

enforcing_mode() {
    local dir raw
    dir=$(policy_dir "$1")
    raw=$(head -n1 "$dir/mode" 2>/dev/null)
    case "${raw,,}" in
        1|enforcing)  echo "enforcing" ;;
        0|permissive) echo "permissive" ;;
        *)            echo "disabled" ;;
    esac
}

count_allowed() {
    local dir
    dir=$(policy_dir "$1")
    grep -c '^[[:space:]]*allow[[:space:]]' "$dir/rules.conf" 2>/dev/null || echo 0
}

count_denied_today() {
    local dir today
    dir=$(policy_dir "$1")
    today=$(date '+%Y-%m-%d')
    grep -c "^${today}.*denied" "$dir/audit.log" 2>/dev/null || echo 0
}

default_context() {
    local dir entry
    dir=$(policy_dir "$1")
    entry=$(grep -m1 "^${2}[[:space:]]*=" "$dir/contexts" 2>/dev/null)
    entry=${entry#*=}
    printf '%s\n' "${entry:-unset}"
}

count_enabled_booleans() {
    local dir
    dir=$(policy_dir "$1")
    grep -ciE '=[[:space:]]*(on|1|true)[[:space:]]*$' "$dir/booleans" 2>/dev/null || echo 0
}

policy_file_path() {
    local dir loaded
    dir=$(policy_dir "$1")
    loaded=$(find "$dir/policy" -maxdepth 1 -type f -name 'policy.*' 2>/dev/null | sort -V | tail -n1)
    printf '%s\n' "${loaded:-none}"
}

policy_mtime() {
    local loaded
    loaded=$(policy_file_path "$1")
    [ -f "$loaded" ] && date -r "$loaded" '+%Y-%m-%d %H:%M:%S' || echo "unknown"
}

count() {
    local policy=$1 dir stats=()
    dir=$(policy_dir "$policy")
    if [ ! -d "$dir" ]; then
        echo "count: unknown policy '$policy' under $POLICY_ROOT" >&2
        return 1
    fi
    stats+=( "$(enforcing_mode "$policy")" )
    stats+=( "$(count_allowed "$policy")" )
    stats+=( "$(count_denied_today "$policy")" )
    stats+=( "$(default_context "$policy" user)" )
    stats+=( "$(default_context "$policy" role)" )
    stats+=( "$(count_enabled_booleans "$policy")" )
    stats+=( "$(policy_file_path "$policy")" )
    stats+=( "$(policy_mtime "$policy")" )
    printf '%s\n' "${stats[@]}"
}

main() {
    local policy=${1:-targeted} idx=0 value
    while IFS= read -r value; do
        printf '%-18s: %s\n' "${FIELD_LABELS[idx]}" "$value"
        idx=$((idx + 1))
    done < <(count "$policy")
}

main "$@"

