#!/usr/bin/env bash
# Collect hypervisor allocation metrics for a libvirt domain.
set -uo pipefail

VIRSH=${VIRSH:-virsh}

vm_uptime_seconds() {
    local pid seconds
    pid=$(pgrep -f "guest=$1," | head -n 1)
    if [ -z "$pid" ]; then
        printf '0\n'
        return
    fi
    seconds=$(ps -o etimes= -p "$pid")
    printf '%s\n' "${seconds//[[:space:]]/}"
}

dominfo_field() {
    printf '%s\n' "$1" | awk -F': +' -v k="$2" '$1==k {print $2; exit}'
}

vm_state() {
    local state
    state=$(dominfo_field "$1" 'State')
    printf '%s\n' "${state:-unknown}"
}

vm_max_memory() {
    local mem
    mem=$(dominfo_field "$1" 'Max memory')
    printf '%s\n' "${mem%% *}"
}

vm_vcpu_count() {
    local cpus
    cpus=$(dominfo_field "$1" 'CPU(s)')
    printf '%s\n' "${cpus:-0}"
}

vm_used_memory() {
    $VIRSH dommemstat "$1" 2>/dev/null |
        awk '$1=="rss"{print $2; hit=1} END{if(!hit) print 0}'
}

vm_os_type() {
    printf '%s\n' "$1" | sed -n 's|.*<type [^>]*>\([^<]*\)</type>.*|\1|p' | head -n 1
}

vm_disk_path() {
    printf '%s\n' "$1" | sed -n "s|.*<source file='\([^']*\)'.*|\1|p" | head -n 1
}

vm_mac_address() {
    printf '%s\n' "$1" | sed -n "s|.*<mac address='\([^']*\)'.*|\1|p" | head -n 1
}

fetch() {
    local domain=$1 info xml
    info=$($VIRSH dominfo "$domain" 2>/dev/null)
    if [ -z "$info" ]; then
        printf 'fetch: domain %s is unknown to the hypervisor\n' "$domain" >&2
        return 1
    fi
    xml=$($VIRSH dumpxml "$domain" 2>/dev/null)
    local state max_mem used_mem vcpus ostype disk mac uptime
    state=$(vm_state "$info")
    max_mem=$(vm_max_memory "$info")
    used_mem=$(vm_used_memory "$domain")
    vcpus=$(vm_vcpu_count "$info")
    ostype=$(vm_os_type "$xml")
    disk=$(vm_disk_path "$xml")
    mac=$(vm_mac_address "$xml")
    uptime=$(vm_uptime_seconds "$domain")
    printf '%s\n' "$state" "$max_mem" "$used_mem" "$vcpus" "$ostype" "$disk" "$mac" "$uptime"
}

main() {
    local domains=("$@") domain metrics
    if [ ${#domains[@]} -eq 0 ]; then
        mapfile -t domains < <($VIRSH list --name 2>/dev/null | sed '/^$/d')
    fi
    for domain in "${domains[@]}"; do
        mapfile -t metrics < <(fetch "$domain") || continue
        printf 'domain=%s state=%s max_mem_kb=%s used_mem_kb=%s vcpus=%s os=%s disk=%s mac=%s uptime_s=%s\n' \
            "$domain" "${metrics[@]}"
    done
}

main "$@"

