#!/usr/bin/env bash
# Monitor in-memory datastore (Redis) cluster members.
set -uo pipefail

REDIS_CLI=${REDIS_CLI:-redis-cli}

node_host() { printf '%s' "${1%:*}"; }

node_port() {
    local port=${1##*:}
    [ "$port" = "$1" ] && port=6379
    printf '%s' "$port"
}

query() {
    local node=$1 host port
    shift
    host=$(node_host "$node")
    port=$(node_port "$node")
    "$REDIS_CLI" -h "$host" -p "$port" "$@" 2>/dev/null | tr -d '\r'
}

field_of() {
    local key=$1
    awk -F: -v k="$key" '$1 == k { print $2; exit }'
}

info_field() {
    local node=$1 section=$2 key=$3
    query "$node" info "$section" | field_of "$key"
}

cluster_field() {
    local node=$1 key=$2
    query "$node" cluster info | field_of "$key"
}

node_identifier() {
    local id
    id=$(query "$1" cluster myid)
    if [ -z "$id" ]; then
        id=$(info_field "$1" server run_id)
    fi
    printf '%s' "${id:-unknown}"
}

node_role() {
    case "$(info_field "$1" replication role)" in
        master) printf 'leader' ;;
        slave)  printf 'follower' ;;
        *)      printf 'unknown' ;;
    esac
}

ping_latency_ms() {
    local start end reply
    start=$(date +%s%N)
    reply=$(query "$1" ping)
    end=$(date +%s%N)
    [ "$reply" = "PONG" ] || { printf '%s' "-1"; return; }
    awk -v s="$start" -v e="$end" 'BEGIN { printf "%.3f", (e - s) / 1000000 }'
}

fetch() {
    local node=$1 metrics=()
    metrics+=("node_id=$(node_identifier "$node")")
    metrics+=("role=$(node_role "$node")")
    metrics+=("connected_replicas=$(info_field "$node" replication connected_slaves)")
    metrics+=("cluster_epoch=$(cluster_field "$node" cluster_my_epoch)")
    metrics+=("assigned_slots=$(cluster_field "$node" cluster_slots_assigned)")
    metrics+=("failover_attempts=$(cluster_field "$node" cluster_stats_messages_failover_auth_request_sent)")
    metrics+=("ping_ms=$(ping_latency_ms "$node")")
    metrics+=("version=$(info_field "$node" server redis_version)")
    printf '%s\n' "${metrics[@]}"
}

if [ "$#" -eq 0 ]; then
    printf 'usage: %s host[:port] [host[:port] ...]\n' "$(basename "$0")" >&2
    exit 2
fi

for target in "$@"; do
    printf '=== %s ===\n' "$target"
    fetch "$target"
done

