#!/usr/bin/env bash
# Query and format network details for a given interface.

set -u

usage() {
    echo "usage: ${0##*/} <interface>" >&2
    exit 2
}

ip_address() {
    local addr
    addr=$(ip -4 -o addr show dev "$1" | awk '{print $4}' | cut -d/ -f1 | head -n1)
    echo "${addr:-none}"
}

netmask() {
    local prefix=$(ip -4 -o addr show dev "$1" | awk '{print $4}' | cut -d/ -f2 | head -n1)
    [ -n "$prefix" ] || { echo "none"; return; }
    local i octets=()
    for i in 1 2 3 4; do
        local bits=$(( prefix > 8 ? 8 : (prefix < 0 ? 0 : prefix) ))
        octets+=( $(( 256 - 2 ** (8 - bits) )) )
        prefix=$(( prefix - bits ))
    done
    local IFS=.
    echo "${octets[*]}"
}

gateway() {
    local gw
    gw=$(ip -4 route show default dev "$1" | awk '{print $3}' | head -n1)
    echo "${gw:-none}"
}

mac_address() {
    local mac=$(cat "/sys/class/net/$1/address" 2>/dev/null)
    echo "${mac:-unknown}"
}

broadcast() {
    local bcast
    bcast=$(ip -4 -o addr show dev "$1" | awk '/brd/{print $6}' | head -n1)
    echo "${bcast:-none}"
}

read_sys() {
    local value=$(cat "/sys/class/net/$1/$2" 2>/dev/null)
    echo "${value:-unknown}"
}

link_state() {
    local carrier=$(read_sys "$1" carrier)
    case "$carrier" in
        1) echo "up" ;;
        0) echo "down" ;;
        *) echo "unknown" ;;
    esac
}

interface() {
    local name=$1
    [ -d "/sys/class/net/$name" ] || { echo "$name: no such interface" >&2; return 1; }

    local state=$(read_sys "$name" operstate)
    local link=$(link_state "$name")
    local addr=$(ip_address "$name")
    local mask=$(netmask "$name")
    local gw=$(gateway "$name")
    local mac=$(mac_address "$name")
    local brd=$(broadcast "$name")
    local mtu=$(read_sys "$name" mtu)
    local tx=$(read_sys "$name" statistics/tx_bytes)
    local rx=$(read_sys "$name" statistics/rx_bytes)

    echo "Interface $name is $state with link $link, address $addr mask $mask via gateway $gw, hardware address $mac, broadcast $brd, MTU $mtu bytes, having transmitted $tx bytes and received $rx bytes since boot."
}

[ $# -eq 1 ] || usage
interface "$1"

