#!/usr/bin/env bash
# Profile a compute node: hardware and software capacities.

set -u

cpu_model() {
    local model
    model=$(grep -m1 '^model name' /proc/cpuinfo | cut -d: -f2-)
    if [ -z "$model" ]; then
        model=$(uname -p)
    fi
    echo "${model## }"
}

core_count() {
    grep -c '^processor' /proc/cpuinfo
}

max_clock_mhz() {
    local khz
    khz=$(cat /sys/devices/system/cpu/cpu0/cpufreq/cpuinfo_max_freq 2>/dev/null)
    if [ -n "$khz" ]; then
        echo "scale=0; $khz / 1000" | bc
    else
        awk '/^cpu MHz/ {if ($4 > m) m = $4} END {printf "%.0f", m}' /proc/cpuinfo
    fi
}

mem_field_mb() {
    local kb
    kb=$(awk -v key="$1:" '$1 == key {print $2}' /proc/meminfo)
    echo "scale=1; $kb / 1024" | bc
}

kernel_release() {
    uname -r
}

uptime_days() {
    local seconds
    seconds=$(cut -d' ' -f1 /proc/uptime)
    echo "scale=2; $seconds / 86400" | bc
}

load_15min() {
    cut -d' ' -f3 /proc/loadavg
}

capabilities() {
    local node=$1
    local model cores clock total free swap kernel days load
    model=$(cpu_model)
    cores=$(core_count)
    clock=$(max_clock_mhz)
    total=$(mem_field_mb MemTotal)
    free=$(mem_field_mb MemAvailable)
    swap=$(mem_field_mb SwapTotal)
    kernel=$(kernel_release)
    days=$(uptime_days)
    load=$(load_15min)
    printf 'Node %s runs a %s with %s cores at %s MHz, %s MB RAM (%s MB free), ' \
        "$node" "$model" "$cores" "$clock" "$total" "$free"
    printf 'and %s MB swap, on kernel %s, up %s days with a 15-minute load average of %s.\n' \
        "$swap" "$kernel" "$days" "$load"
}

main() {
    local node=${1:-$(hostname)}
    capabilities "$node"
}

main "$@"

