#!/usr/bin/env bash
# issue.sh - generate and register a new SSL certificate for a web domain
set -uo pipefail

KEY_DIR="${KEY_DIR:-/tmp/ssl-keys}"
ADMIN_CONF="${ADMIN_CONF:-/etc/ssl-issuer.conf}"

generate_key() {
    local domain="$1"
    local path="$KEY_DIR/${domain}.key"
    mkdir -p "$KEY_DIR"
    openssl genrsa -out "$path" 2048 >/dev/null 2>&1 || return 1
    chmod 600 "$path"
    printf '%s\n' "$path"
}

current_year() {
    date +%Y
}

expiration_date() {
    local today
    today=$(date +%Y-%m-%d)
    date -d "$today +1 year" +%Y-%m-%d 2>/dev/null || date -v+1y -j -f %Y-%m-%d "$today" +%Y-%m-%d
}

key_fingerprint() {
    local path="$1" digest
    digest=$(openssl rsa -in "$path" -pubout -outform DER 2>/dev/null | openssl dgst -sha256 -hex)
    printf '%s\n' "${digest##*= }"
}

serial_number() {
    openssl rand -hex 8 | tr 'a-f' 'A-F'
}

admin_email() {
    local configured
    configured=$(sed -n 's/^admin_email[[:space:]]*=[[:space:]]*//p' "$ADMIN_CONF" 2>/dev/null | head -n 1)
    if [[ -n "$configured" ]]; then
        printf '%s\n' "$configured"
    else
        local host
        host=$(hostname -f 2>/dev/null || hostname)
        printf 'root@%s\n' "$host"
    fi
}

external_ip() {
    curl -fsS --max-time 5 https://api.ipify.org 2>/dev/null || printf '0.0.0.0\n'
}

issuer_fqdn() {
    hostname -f 2>/dev/null || hostname
}

issue() {
    local domain="$1"
    local start_ns end_ns key_path elapsed
    start_ns=$(date +%s%N)
    key_path=$(generate_key "$domain") || { echo "issue: key generation failed for $domain" >&2; return 1; }
    end_ns=$(date +%s%N)
    elapsed=$(awk -v s="$start_ns" -v e="$end_ns" 'BEGIN { printf "%.2f", (e - s) / 1000000000 }')

    local year expires fingerprint serial email ip issuer
    year=$(current_year)
    expires=$(expiration_date)
    fingerprint=$(key_fingerprint "$key_path")
    serial=$(serial_number)
    email=$(admin_email)
    ip=$(external_ip)
    issuer=$(issuer_fqdn)

    echo "Certificate issued for $domain using key $key_path, valid from $year until $expires, fingerprint $fingerprint, serial $serial, registered to $email from $ip by issuer $issuer in ${elapsed}s."
}

main() {
    if [[ $# -ne 1 ]]; then
        echo "usage: ${0##*/} <domain>" >&2
        return 2
    fi
    issue "$1"
}

main "$@"

