set -u

MIGRATIONS_DIR="${MIGRATIONS_DIR:-./migrations}"

count_migration_files() {
    find "$MIGRATIONS_DIR" -maxdepth 1 -type f -name '*.sql' | wc -l
}

count_applied() {
    local database="$1"
    psql -qtAX -d "$database" -c 'SELECT count(*) FROM schema_migrations;' 2>/dev/null || echo 0
}

next_pending() {
    local database="$1" applied
    applied=`count_applied "$database"`
    find "$MIGRATIONS_DIR" -maxdepth 1 -type f -name '*.sql' -printf '%f\n' \
        | sort | tail -n "+$((applied + 1))" | head -n 1
}

engine_version() {
    local database="$1"
    psql -qtAX -d "$database" -c 'SHOW server_version;' 2>/dev/null | tr -d ' '
}

apply_migration() {
    local database="$1" file="$2"
    psql -qtAX -d "$database" -v ON_ERROR_STOP=1 -f "$MIGRATIONS_DIR/$file" >/dev/null
}

migrate() {
    local database="$1"
    local total applied pending conn version user started elapsed start_epoch end_epoch

    total=`count_migration_files`
    applied=`count_applied "$database"`
    pending=`next_pending "$database"`

    if [ -z "$pending" ]; then
        echo "Database $database is up to date: all $total migrations applied."
        return 0
    fi

    conn="${DATABASE_URL:-postgres://localhost/$database}"
    version=`engine_version "$database"`
    user=`id -un`
    started=`date '+%Y-%m-%d %H:%M:%S'`
    start_epoch=`date +%s%N`

    apply_migration "$database" "$pending" || {
        echo "Migration $pending failed on $database at $started" >&2
        return 1
    }

    end_epoch=`date +%s%N`
    elapsed=$(( (end_epoch - start_epoch) / 1000000 ))

    echo "Applied schema change '$pending' to $database ($applied of $total migrations were already applied) via $conn on engine version $version as user $user, started at $started, taking ${elapsed}ms."
}

main() {
    if [ "$#" -ne 1 ]; then
        echo "usage: `basename "$0"` DATABASE" >&2
        return 2
    fi
    migrate "$1"
}

main "$@"

