#!/usr/bin/env bash
# Inspect an isolated Python environment and report its configuration.

set -uo pipefail

site_packages_dir() {
    local env="$1"
    find "$env/lib" -maxdepth 2 -type d -name 'site-packages' 2>/dev/null | head -n 1
}

interpreter_version() {
    local py="$1/bin/python"
    [ -x "$py" ] || return 1
    "$py" --version 2>&1 | awk '{print $2}'
}

environment_root() {
    cd "$1" && pwd -P
}

library_count() {
    local site
    site="$(site_packages_dir "$1")"
    find "$site" -maxdepth 1 -name '*.dist-info' -type d 2>/dev/null | wc -l | tr -d ' '
}

installer_version() {
    local pip="$1/bin/pip"
    [ -x "$pip" ] || return 1
    "$pip" --version 2>/dev/null | awk '{print $2}'
}

largest_library() {
    local site="$1" biggest
    biggest="$(du -s "$site"/*/ 2>/dev/null | sort -rn | head -n 1 | cut -f2)"
    basename "${biggest:-none}"
}

total_library_size() {
    du -sh "$1" 2>/dev/null | cut -f1
}

binary_path_status() {
    case ":$PATH:" in
        *":$1/bin:"*) echo "present in PATH" ;;
        *) echo "absent from PATH" ;;
    esac
}

creation_date() {
    local stamp
    stamp="$(stat -c %w "$1" 2>/dev/null)"
    [ -n "$stamp" ] && [ "$stamp" != "-" ] || stamp="$(stat -c %y "$1")"
    echo "${stamp%%.*}"
}

default_encoding() {
    "$1/bin/python" -c 'import sys; print(sys.getdefaultencoding())' 2>/dev/null
}

analyze() {
    local environment="$1" root site
    if [ ! -d "$environment" ]; then
        echo "error: '$environment' is not a directory" >&2
        return 1
    fi
    root="$(environment_root "$environment")"
    site="$(site_packages_dir "$root")"
    if [ -z "$site" ]; then
        echo "error: no site-packages found under '$root'" >&2
        return 1
    fi
    printf 'The environment at %s runs interpreter version %s' \
        "$root" "$(interpreter_version "$root")"
    printf ' with package installer %s' "$(installer_version "$root")"
    printf ', holds %s third party libraries' "$(library_count "$root")"
    printf ' occupying %s in total' "$(total_library_size "$site")"
    printf ' (largest: %s)' "$(largest_library "$site")"
    printf ', was created on %s' "$(creation_date "$root")"
    printf ', uses %s as default encoding' "$(default_encoding "$root")"
    printf ' and its binary folder is %s.\n' "$(binary_path_status "$root")"
}

analyze "${1:-.}"

