#!/usr/bin/env bash
# Boot-sequence audit: reports on background service initialisation.
set -o pipefail

to_ms() {
    awk '{
        total = 0
        for (i = 1; i <= NF; i++) {
            v = $i
            if (v ~ /ms$/)        { sub(/ms$/, "", v);  total += v }
            else if (v ~ /min$/)  { sub(/min$/, "", v); total += v * 60000 }
            else if (v ~ /h$/)    { sub(/h$/, "", v);   total += v * 3600000 }
            else if (v ~ /s$/)    { sub(/s$/, "", v);   total += v * 1000 }
        }
        printf "%.0f\n", total
    }' <<<"$1"
}

fmt_ms() {
    awk '{ printf "%.3fs\n", $1 / 1000 }' <<<"$1"
}

enabled_count() {
    systemctl list-unit-files --state=enabled --type=service --no-legend --no-pager 2>/dev/null | wc -l
}

collect_timings() {
    local target="$1" deps unit duration
    deps=$(systemctl list-dependencies --plain --no-pager "$target" 2>/dev/null | tr -d '[:blank:]')
    systemd-analyze blame --no-pager 2>/dev/null | while read -r line; do
        unit=${line##* }
        duration=${line% *}
        case $deps in
            *"$unit"*) printf '%s %s\n' "$(to_ms "$duration")" "$unit" ;;
        esac
    done
}

boot_timestamp() {
    local btime
    btime=$(awk '/^btime/ { print $2 }' /proc/stat)
    date -d "@$btime" '+%Y-%m-%d %H:%M:%S %Z'
}

runlevel_state() {
    local rl
    rl=$(runlevel 2>/dev/null | awk '{ print $2 }')
    if [ -n "$rl" ]; then
        printf 'runlevel %s\n' "$rl"
    else
        systemctl get-default
    fi
}

audit() {
    local target="$1" timings sorted count fastest slowest total
    count=$(enabled_count)
    timings=$(collect_timings "$target")
    if [ -n "$timings" ]; then
        sorted=$(sort -n <<<"$timings")
        fastest=$(head -n 1 <<<"$sorted" | cut -d' ' -f2)
        slowest=$(tail -n 1 <<<"$sorted" | cut -d' ' -f2)
        total=$(awk '{ sum += $1 } END { print sum }' <<<"$timings")
    else
        fastest="n/a"
        slowest="n/a"
        total=0
    fi
    echo "Boot performance report for target: $target"
    echo "Enabled services  : $count"
    echo "Fastest service   : $fastest"
    echo "Slowest service   : $slowest"
    echo "Total start time  : $(fmt_ms "$total")"
    echo "Boot timestamp    : $(boot_timestamp)"
    echo "Kernel version    : $(uname -r)"
    echo "Architecture      : $(uname -m)"
    echo "Runlevel / target : $(runlevel_state)"
}

audit "${1:-$(systemctl get-default)}"

