#!/usr/bin/env bash
# Replace every occurrence of a literal substring inside a string.
set -uo pipefail

usage() {
    local prog
    prog=$(basename "$0")
    printf 'usage: %s [-v|--verbose] <string> <find> <replace>\n' "$prog" >&2
    exit 2
}

die() {
    printf 'error: %s\n' "$1" >&2
    exit 1
}

# Print $1 with every literal occurrence of $2 turned into $3.
replace_all() {
    local haystack=$1 needle=$2 sub=$3 prefix out=''
    while [[ $haystack == *"$needle"* ]]; do
        prefix=${haystack%%"$needle"*}
        out+=$prefix$sub
        haystack=${haystack:$((${#prefix} + ${#needle}))}
    done
    printf '%s' "$out$haystack"
}

# How many times $2 occurs in $1: drop them all and measure the shrinkage.
count_occurrences() {
    local haystack=$1 needle=$2 stripped
    stripped=$(replace_all "$haystack" "$needle" '')
    printf '%s' $(((${#haystack} - ${#stripped}) / ${#needle}))
}

quote_literal() {
    printf '%q' "$1"
}

# One-line report about the substitution that is about to be performed.
summarize() {
    local original=$1 needle=$2 sub=$3 count needle_q sub_q
    count=$(count_occurrences "$original" "$needle")
    needle_q=$(quote_literal "$needle")
    sub_q=$(quote_literal "$sub")
    printf 'replacing %s with %s: %d occurrence(s)\n' "$needle_q" "$sub_q" "$count"
}

main() {
    local verbose=0 result
    if [[ ${1:-} == -v || ${1:-} == --verbose ]]; then
        verbose=1
        shift
    fi
    (($# == 3)) || usage
    [[ -n $2 ]] || die "the find string must not be empty"

    if ((verbose)); then
        summarize "$1" "$2" "$3" >&2
    fi

    result=$(replace_all "$1" "$2" "$3")
    printf '%s\n' "$result"
}

main "$@"

