#!/usr/bin/env bash
# Report whether the single argument names an existing directory.

set -u

main() {
    if [ "$#" -ne 1 ]; then
        usage
        return 2
    fi

    local path status
    path=$(normalize "$1")
    status=$(classify "$path")

    message_for "$status"

    [ "$status" = directory ]
}

usage() {
    printf 'usage: %s PATH\n' "$(basename "$0")" >&2
}

# Expand a leading ~ so hand-typed home-relative paths are checked correctly.
expand_home() {
    case "$1" in
        "~")
            printf '%s\n' "$HOME"
            ;;
        "~/"*)
            printf '%s/%s\n' "$HOME" "${1#"~/"}"
            ;;
        *)
            printf '%s\n' "$1"
            ;;
    esac
}

# "dir//sub" and "dir/sub" name the same entry, so squeeze repeated slashes.
collapse_slashes() {
    printf '%s\n' "$1" | tr -s '/'
}

# Drop redundant trailing slashes, keeping a lone "/" intact.
trim_slashes() {
    local path="$1"
    while [ "${#path}" -gt 1 ] && [ "${path%/}" != "$path" ]; do
        path="${path%/}"
    done
    printf '%s\n' "$path"
}

normalize() {
    local expanded collapsed
    expanded=$(expand_home "$1")
    collapsed=$(collapse_slashes "$expanded")
    trim_slashes "$collapsed"
}

classify() {
    local path="$1"

    if [ -d "$path" ]; then
        echo directory
    elif [ -e "$path" ] || [ -L "$path" ]; then
        echo other
    else
        echo missing
    fi
}

message_for() {
    case "$1" in
        directory)
            echo "Is a directory."
            ;;
        *)
            echo "Not a directory or does not exist."
            ;;
    esac
}

main "$@"

