#!/usr/bin/env bash
#
# Recursively count the files with a given extension under a directory.
#
#   script.sh /home/user .pdf
#   script.sh /var/www html
#
set -uo pipefail

usage() {
    printf 'Usage: %s <directory> <extension>\n' "${0##*/}" >&2
}

# Accept both "txt" and ".txt" spellings.
normalize_ext() {
    local ext=$1
    printf '%s\n' "${ext#.}"
}

# Turn the user supplied path into an absolute one (and verify it exists).
resolve_dir() {
    local abs
    abs=$(cd -- "$1" 2>/dev/null && pwd) || return 1
    printf '%s\n' "$abs"
}

# One dot per match is printed, so file names with newlines cannot skew things.
count_files() {
    local total
    total=$(find "$1" -type f -iname "*.$2" -printf '.' 2>/dev/null | wc -c)
    printf '%s\n' "$total"
}

total_size() {
    local bytes
    bytes=$(find "$1" -type f -iname "*.$2" -printf '%s\n' 2>/dev/null | awk '{s += $1} END {print s + 0}')
    printf '%s\n' "$bytes"
}

format_size() {
    awk -v b="$1" 'BEGIN {
        split("B KiB MiB GiB TiB", u, " ")
        i = 1
        while (b >= 1024 && i < 5) { b /= 1024; i++ }
        printf (i == 1 ? "%d %s\n" : "%.1f %s\n"), b, u[i]
    }'
}

largest_file() {
    local line
    line=$(find "$1" -type f -iname "*.$2" -printf '%s\t%p\n' 2>/dev/null | sort -nr | head -n 1)
    printf '%s\n' "${line#*$'\t'}"
}

main() {
    if [[ $# -ne 2 ]]; then
        usage
        return 2
    fi

    local root ext count bytes
    root=$(resolve_dir "$1") || {
        printf '%s: not a readable directory\n' "$1" >&2
        return 1
    }
    ext=$(normalize_ext "$2")
    if [[ -z $ext ]]; then
        printf 'extension must not be empty\n' >&2
        return 2
    fi

    count=$(count_files "$root" "$ext")
    printf '%s\n' "$count"

    if (( count > 0 )); then
        bytes=$(total_size "$root" "$ext")
        printf '%s files matching *.%s under %s, %s total\n' \
            "$count" "$ext" "$root" "$(format_size "$bytes")" >&2
        printf 'largest: %s\n' "$(largest_file "$root" "$ext")" >&2
    fi
}

main "$@"

