#!/usr/bin/env bash
# Count and print the number of processes currently running on the system.
set -uo pipefail

usage() {
    printf 'usage: %s [-v|--verbose]\n' "${0##*/}"
}

have_ps() {
    command -v ps >/dev/null 2>&1
}

# Count process entries reported by ps (one pid per line, no header).
count_via_ps() {
    local lines
    lines=$(ps -e -o pid= | wc -l)
    printf '%d\n' "$lines"
}

# Fallback for systems without ps: numeric directories under /proc.
count_via_proc() {
    local dir count=0
    for dir in /proc/[0-9]*; do
        [ -d "$dir" ] && count=$((count + 1))
    done
    printf '%d\n' "$count"
}

total_process_count() {
    if have_ps; then
        count_via_ps
    else
        count_via_proc
    fi
}

# Number of processes whose state code starts with the given letter.
count_in_state() {
    local state=$1 matches
    matches=$(ps -e -o stat= | grep -c "^${state}")
    printf '%d\n' "$matches"
}

total_thread_count() {
    local lines
    lines=$(ps -eL -o tid= | wc -l)
    printf '%d\n' "$lines"
}

state_report() {
    local total=$1 state count threads
    threads=$(total_thread_count)
    printf 'processes : %s\n' "$total"
    printf 'threads   : %s\n' "$threads"
    for state in R S D T Z; do
        count=$(count_in_state "$state")
        printf 'state %s   : %s\n' "$state" "$count"
    done
}

main() {
    local verbose=0 total
    while [ $# -gt 0 ]; do
        case $1 in
            -v|--verbose) verbose=1 ;;
            -h|--help) usage; return 0 ;;
            *) printf 'unknown option: %s\n' "$1" >&2; usage >&2; return 2 ;;
        esac
        shift
    done

    total=$(total_process_count)
    if [ "$verbose" -eq 1 ] && have_ps; then
        state_report "$total"
    else
        printf '%s\n' "$total"
    fi
}

main "$@"

