#!/usr/bin/env bash
# encode.sh - print the Base64 encoding of a string given on the command line.
set -euo pipefail

usage() {
    local prog
    prog=$(basename "$0")
    cat <<EOF
Usage: $prog [-d] [-w WIDTH] STRING

  -d        decode STRING from Base64 instead of encoding it
  -w WIDTH  wrap the output into lines of WIDTH characters
  -h        show this help text

Example: $prog "Hello World"   ->  SGVsbG8gV29ybGQ=
EOF
}

die() {
    printf '%s: %s\n' "$(basename "$0")" "$1" >&2
    exit 1
}

# Pick whichever Base64 implementation is installed on this machine.
detect_codec() {
    if [ -x "$(command -v base64 2>/dev/null)" ]; then
        echo base64
    elif [ -x "$(command -v openssl 2>/dev/null)" ]; then
        echo openssl
    else
        return 1
    fi
}

encode_string() {
    local data=$1 codec=$2
    case $codec in
        base64)  printf '%s' "$data" | base64 | tr -d '\n' ;;
        openssl) printf '%s' "$data" | openssl base64 -A ;;
    esac
}

decode_string() {
    local data=$1 codec=$2
    case $codec in
        base64)  printf '%s' "$data" | base64 --decode ;;
        openssl) printf '%s' "$data" | openssl base64 -d -A ;;
    esac
}

main() {
    local mode=encode width=0 opt input codec result
    while getopts ":dw:h" opt; do
        case $opt in
            d) mode=decode ;;
            w) width=$OPTARG ;;
            h) usage; return 0 ;;
            *) usage >&2; return 1 ;;
        esac
    done
    shift $((OPTIND - 1))

    [ $# -eq 1 ] || { usage >&2; return 1; }
    input=$1

    case $width in
        ''|*[!0-9]*) die "invalid wrap width: $width" ;;
    esac

    codec=$(detect_codec) || die "no base64 or openssl command available"

    if [ "$mode" = decode ]; then
        result=$(decode_string "$input" "$codec") || die "input is not valid Base64"
    else
        result=$(encode_string "$input" "$codec")
    fi

    if [ "$width" -gt 0 ]; then
        fold -w "$width" <<<"$result"
    else
        printf '%s\n' "$result"
    fi
}

main "$@"

