#!/usr/bin/env bash
# extract_username.sh - print the username part of an email address.

set -u

usage() {
    printf 'Usage: %s EMAIL\n' "$(basename "$0")" >&2
}

# Strip surrounding whitespace so quoted arguments with stray spaces work.
trim() {
    local text=$1
    text=${text#"${text%%[![:space:]]*}"}
    text=${text%"${text##*[![:space:]]}"}
    printf '%s' "$text"
}

extract_username() {
    local address
    address=$(trim "$1")
    printf '%s' "${address%%@*}"
}

extract_domain() {
    local address
    address=$(trim "$1")
    printf '%s' "${address#*@}"
}

count_at_signs() {
    local address=$1 stripped
    stripped=${address//@/}
    printf '%d' $(( ${#address} - ${#stripped} ))
}

validate_email() {
    local address
    address=$(trim "$1")

    if [ "$(count_at_signs "$address")" -ne 1 ]; then
        printf 'error: address must contain exactly one "@": %s\n' "$address" >&2
        return 1
    fi

    if [ -z "$(extract_username "$address")" ]; then
        printf 'error: missing username before "@": %s\n' "$address" >&2
        return 1
    fi

    local domain
    domain=$(extract_domain "$address")
    if [ -z "$domain" ] || [ "${domain#*.}" = "$domain" ]; then
        printf 'error: invalid domain part: %s\n' "$domain" >&2
        return 1
    fi

    return 0
}

main() {
    if [ "$#" -ne 1 ]; then
        usage
        return 2
    fi

    local address
    address=$(trim "$1")
    validate_email "$address" || return 1

    printf '%s\n' "$(extract_username "$address")"
}

main "$@"

