#!/usr/bin/env bash
# self_name.sh - report the script's own filename (and, on request, related facts).

set -u

script_source() {
    # The path the shell was given for this script, however it was invoked.
    printf '%s\n' "${BASH_SOURCE[0]:-$0}"
}

script_name() {
    local src
    src=$(script_source)
    basename -- "$src"
}

script_path() {
    local src dir base
    src=$(script_source)
    if command -v realpath >/dev/null 2>&1; then
        realpath -- "$src"
        return
    fi
    dir=$(dirname -- "$src")
    base=$(basename -- "$src")
    dir=$(cd -- "$dir" && pwd -P)
    printf '%s/%s\n' "$dir" "$base"
}

script_dir() {
    local path
    path=$(script_path)
    dirname -- "$path"
}

script_size() {
    local path
    path=$(script_path)
    wc -c <"$path" | tr -d ' '
}

script_lines() {
    local path
    path=$(script_path)
    grep -c '' -- "$path"
}

report_info() {
    local name size lines
    name=$(script_name)
    size=$(script_size)
    lines=$(script_lines)
    printf 'name:  %s\n' "$name"
    printf 'dir:   %s\n' "$(script_dir)"
    printf 'path:  %s\n' "$(script_path)"
    printf 'bytes: %s\n' "$size"
    printf 'lines: %s\n' "$lines"
}

usage() {
    local name
    name=$(script_name)
    printf 'usage: %s [--name|--path|--dir|--info]\n' "$name"
}

main() {
    case "${1:---name}" in
        --name) script_name ;;
        --path) script_path ;;
        --dir)  script_dir ;;
        --info) report_info ;;
        --help) usage ;;
        *)
            printf 'unknown option: %s\n' "$1" >&2
            usage >&2
            return 2
            ;;
    esac
}

main "$@"

