#!/usr/bin/env bash
#
# arg_count.sh - print the total number of command-line arguments received.
#
# stdout always carries just the count. With ARGCOUNT_VERBOSE=1 a listing of
# the arguments is written to stderr for debugging.

set -u

program_name=$(basename "$0")
start_time=$(date '+%Y-%m-%d %H:%M:%S')

plural_label() {
    if [ "$1" -eq 1 ]; then
        printf 'argument\n'
    else
        printf 'arguments\n'
    fi
}

sanitize() {
    printf '%s' "$1" | tr -c '[:print:]' '.'
}

total_bytes() {
    printf '%s' "$*" | wc -c | tr -d '[:space:]'
}

longest_length() {
    local max=0 arg
    for arg in "$@"; do
        if [ "${#arg}" -gt "$max" ]; then
            max=${#arg}
        fi
    done
    printf '%s\n' "$max"
}

describe_arg() {
    local index=$1 value=$2 text
    text=$(sanitize "$value")
    printf '  [%d] %s (%d chars)\n' "$index" "$text" "${#value}"
}

render_summary() {
    local total=$#
    printf '%s at %s\n' "$program_name" "$start_time"
    printf 'received %s %s\n' "$total" "$(plural_label "$total")"
    if [ "$total" -gt 0 ]; then
        local bytes longest
        bytes=$(total_bytes "$@")
        longest=$(longest_length "$@")
        printf 'payload %s bytes, longest argument %s chars\n' "$bytes" "$longest"
    fi
    local index=1 arg
    for arg in "$@"; do
        describe_arg "$index" "$arg"
        index=$((index + 1))
    done
}

verbose_enabled() {
    case "${ARGCOUNT_VERBOSE:-0}" in
        1|yes|true) return 0 ;;
        *)          return 1 ;;
    esac
}

main() {
    if verbose_enabled; then
        render_summary "$@" >&2
    fi
    printf '%s\n' "$#"
}

main "$@"

