#!/usr/bin/env bash
#
# palindrome.sh - report whether the string given on the command line reads
# the same forwards and backwards, ignoring letter case.

set -u

script_name() {
    basename "$0"
}

usage() {
    local prog
    prog=$(script_name)
    printf 'usage: %s <string>\n' "$prog" >&2
}

die() {
    local prog
    prog=$(script_name)
    printf '%s: %s\n' "$prog" "$1" >&2
    usage
    exit 2
}

main() {
    (($# == 1)) || die "expected exactly one argument, got $#"

    local verdict
    verdict=$(verdict_for "$1")
    printf '%s\n' "$verdict"
    [[ $verdict == True ]]
}

# Fold letters to lower case so that the comparison ignores case.
to_lower() {
    printf '%s' "$1" | tr '[:upper:]' '[:lower:]'
}

# Reverse a string one character at a time, without an external tool.
reverse_string() {
    local subject=$1 out='' i
    for ((i = ${#subject} - 1; i >= 0; i--)); do
        out+=${subject:i:1}
    done
    printf '%s' "$out"
}

# Succeeds when the argument is a palindrome.
is_palindrome() {
    local forwards backwards
    forwards=$(to_lower "$1")
    backwards=$(reverse_string "$forwards")
    [[ $forwards == "$backwards" ]]
}

# Render the outcome of the test as the word the task asks for.
verdict_for() {
    if is_palindrome "$1"; then
        printf 'True'
    else
        printf 'False'
    fi
}

main "$@"

